import { Test, TestingModule } from '@nestjs/testing';
import { UnauthorizedException } from '@nestjs/common';
import { ThrottlerModule } from '@nestjs/throttler';

// Mock AuthService at the module level to prevent requireEnv() from firing
// during module load (it calls bcrypt.hashSync(requireEnv(...)) at top level).
jest.mock('./auth.service', () => ({
  AuthService: jest.fn().mockImplementation(() => ({
    login: jest.fn(),
  })),
}));

import { AuthController } from './auth.controller';
import { AuthService } from './auth.service';

describe('AuthController', () => {
  let controller: AuthController;
  let service: any;

  // eslint-disable-next-line no-restricted-syntax
  const mockToken = { access_token: 'jwt.token.here' }; // TEST_CREDENTIAL

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      imports: [ThrottlerModule.forRoot([{ ttl: 60000, limit: 10 }])],
      controllers: [AuthController],
      providers: [
        {
          provide: AuthService,
          useValue: { login: jest.fn().mockResolvedValue(mockToken) },
        },
      ],
    }).compile();

    controller = module.get<AuthController>(AuthController);
    service = module.get(AuthService);
  });

  describe('login', () => {
    it('should return a JWT token for valid credentials', async () => {
      const result = await controller.login({
        username: 'admin',
        // eslint-disable-next-line no-restricted-syntax
        password: 'password123', // TEST_CREDENTIAL
      });
      expect(result).toEqual(mockToken);
      expect(service.login).toHaveBeenCalledWith('admin', 'password123');
    });

    it('should propagate UnauthorizedException from service', async () => {
      service.login.mockRejectedValueOnce(
        new UnauthorizedException('Invalid credentials'),
      );
      await expect(
        // eslint-disable-next-line no-restricted-syntax
        controller.login({ username: 'bad', password: 'wrong' }), // TEST_CREDENTIAL
      ).rejects.toThrow(UnauthorizedException);
    });

    it('should pass username and password from DTO body', async () => {
      // eslint-disable-next-line no-restricted-syntax
      await controller.login({ username: 'viewer', password: 'REDACTED' }); // TEST_CREDENTIAL
      expect(service.login).toHaveBeenCalledWith('viewer', 'REDACTED');
    });
  });
});

import {
  ApiTags,
  ApiOperation,
  ApiOkResponse,
  ApiCreatedResponse,
  ApiBody,
} from '@nestjs/swagger';
import {
  Controller,
  Post,
  Get,
  Body,
  UseGuards,
  Request,
} from '@nestjs/common';
import { IsString, IsNotEmpty } from 'class-validator';
import { AuthGuard } from '@nestjs/passport';
import { AuthService } from './auth.service';
import { SkipCasbin } from './casbin.guard';
import { ThrottlerGuard, Throttle } from '@nestjs/throttler';
import { LoginDto, LoginResponseDto, MeResponseDto } from './dto';

@ApiTags('System')
@Controller('auth')
@SkipCasbin()
export class AuthController {
  constructor(private authService: AuthService) {}

  @Post('login')
  @ApiBody({ type: LoginDto })
  @ApiCreatedResponse({ type: LoginResponseDto })
  @SkipCasbin()
  @UseGuards(ThrottlerGuard)
  @Throttle({
    default: { limit: process.env.NODE_ENV === 'test' ? 100 : 5, ttl: 60000 },
  })
  @ApiOperation({
    summary: 'Login User',
    description: 'Authenticates a user and returns a JWT token.',
  })
  async login(@Body() dto: LoginDto) {
    return this.authService.login(dto.username, dto.password);
  }

  /** Return the current user's identity from JWT — used by frontend for role-aware UI. */
  @Get('me')
  @ApiOkResponse({ type: MeResponseDto })
  @SkipCasbin()
  @UseGuards(ThrottlerGuard, AuthGuard(['jwt', 'api-key']))
  @Throttle({
    default: { limit: process.env.NODE_ENV === 'test' ? 100 : 30, ttl: 60000 },
  })
  @ApiOperation({
    summary: 'Get Current User',
    description:
      'Returns the identity and role of the currently authenticated user.',
  })
  me(@Request() req: any) {
    return {
      username: req.user.username,
      role: req.user.role,
    };
  }
}

import { Reflector } from '@nestjs/core';
import {
  ExecutionContext,
  ForbiddenException,
  UnauthorizedException,
} from '@nestjs/common';
import {
  CasbinGuard,
  CASBIN_RESOURCE,
  CASBIN_ACTION,
  SKIP_CASBIN,
} from './casbin.guard';
import { newEnforcer } from 'casbin';
import * as path from 'path';
import * as fs from 'fs';

function resolveCasbinAsset(filename: string): string {
  const dirPath = path.join(__dirname, 'casbin', filename);
  if (fs.existsSync(dirPath)) return dirPath;

  const srcPath = path.join(
    process.cwd(),
    'apps',
    'api',
    'src',
    'auth',
    'casbin',
    filename,
  );
  if (fs.existsSync(srcPath)) return srcPath;

  const srcPath2 = path.join(process.cwd(), 'src', 'auth', 'casbin', filename);
  if (fs.existsSync(srcPath2)) return srcPath2;

  return dirPath;
}

/**
 * Helper to build a mock ExecutionContext with configurable metadata and request.
 */
function createMockContext(opts: {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  metadata?: Record<string, any>;
  user?: { userId: string; username: string; role: string } | null;
}): ExecutionContext {
  const handler = jest.fn();
  const classRef = jest.fn();

  return {
    getHandler: () => handler,
    getClass: () => classRef,
    switchToHttp: () => ({
      getRequest: () => ({ user: opts.user ?? undefined }),
      getResponse: jest.fn(),
      getNext: jest.fn(),
    }),
    // Store metadata so Reflector mock can retrieve it
    __metadata: opts.metadata ?? {},
    __handler: handler,
    __classRef: classRef,
  } as unknown as ExecutionContext & {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    __metadata: Record<string, any>;
    __handler: any;
    __classRef: any;
  };
}

describe('CasbinGuard', () => {
  let guard: CasbinGuard;
  let reflector: Reflector;
  let enforcer: any;

  beforeAll(async () => {
    const modelPath = resolveCasbinAsset('model.conf');
    const policyPath = resolveCasbinAsset('policy.csv');
    enforcer = await newEnforcer(modelPath, policyPath);
  });

  beforeEach(() => {
    reflector = new Reflector();
    guard = new CasbinGuard(reflector, enforcer);
  });

  describe('SkipCasbin decorator', () => {
    it('should allow access when @SkipCasbin() is set', async () => {
      const ctx = createMockContext({
        metadata: { [SKIP_CASBIN]: true },
        user: null,
      });

      // Mock reflector to return skip_casbin = true
      jest
        .spyOn(reflector, 'getAllAndOverride')
        .mockImplementation((key: string) => {
          return (ctx as any).__metadata[key];
        });

      const result = await guard.canActivate(ctx);
      expect(result).toBe(true);
    });
  });

  describe('Missing decorators (deny-by-default)', () => {
    it('should throw ForbiddenException when @CasbinResource is missing', async () => {
      const ctx = createMockContext({
        metadata: { [CASBIN_ACTION]: 'read' },
        user: { userId: '1', username: 'admin', role: 'admin' },
      });

      jest
        .spyOn(reflector, 'getAllAndOverride')
        .mockImplementation((key: string) => {
          return (ctx as any).__metadata[key];
        });

      await expect(guard.canActivate(ctx)).rejects.toThrow(ForbiddenException);
    });

    it('should throw ForbiddenException when @CasbinAction is missing', async () => {
      const ctx = createMockContext({
        metadata: { [CASBIN_RESOURCE]: 'products' },
        user: { userId: '1', username: 'admin', role: 'admin' },
      });

      jest
        .spyOn(reflector, 'getAllAndOverride')
        .mockImplementation((key: string) => {
          return (ctx as any).__metadata[key];
        });

      await expect(guard.canActivate(ctx)).rejects.toThrow(ForbiddenException);
    });

    it('should throw ForbiddenException when both decorators are missing', async () => {
      const ctx = createMockContext({
        metadata: {},
        user: { userId: '1', username: 'admin', role: 'admin' },
      });

      jest
        .spyOn(reflector, 'getAllAndOverride')
        .mockImplementation((key: string) => {
          return (ctx as any).__metadata[key];
        });

      await expect(guard.canActivate(ctx)).rejects.toThrow(ForbiddenException);
    });
  });

  describe('Unauthenticated request', () => {
    it('should throw UnauthorizedException when no user is present', async () => {
      const ctx = createMockContext({
        metadata: {
          [CASBIN_RESOURCE]: 'products',
          [CASBIN_ACTION]: 'read',
        },
        user: null,
      });

      jest
        .spyOn(reflector, 'getAllAndOverride')
        .mockImplementation((key: string) => {
          return (ctx as any).__metadata[key];
        });

      await expect(guard.canActivate(ctx)).rejects.toThrow(
        UnauthorizedException,
      );
    });
  });

  describe('Policy enforcement', () => {
    it('should allow viewer to read products', async () => {
      const ctx = createMockContext({
        metadata: {
          [CASBIN_RESOURCE]: 'products',
          [CASBIN_ACTION]: 'read',
        },
        user: { userId: '2', username: 'viewer', role: 'viewer' },
      });

      jest
        .spyOn(reflector, 'getAllAndOverride')
        .mockImplementation((key: string) => {
          return (ctx as any).__metadata[key];
        });

      const result = await guard.canActivate(ctx);
      expect(result).toBe(true);
    });

    it('should deny viewer from writing users', async () => {
      const ctx = createMockContext({
        metadata: {
          [CASBIN_RESOURCE]: 'users',
          [CASBIN_ACTION]: 'write',
        },
        user: { userId: '2', username: 'viewer', role: 'viewer' },
      });

      jest
        .spyOn(reflector, 'getAllAndOverride')
        .mockImplementation((key: string) => {
          return (ctx as any).__metadata[key];
        });

      await expect(guard.canActivate(ctx)).rejects.toThrow(ForbiddenException);
    });

    it('should allow admin to write sales-orders', async () => {
      const ctx = createMockContext({
        metadata: {
          [CASBIN_RESOURCE]: 'sales-orders',
          [CASBIN_ACTION]: 'write',
        },
        user: { userId: '1', username: 'admin', role: 'admin' },
      });

      jest
        .spyOn(reflector, 'getAllAndOverride')
        .mockImplementation((key: string) => {
          return (ctx as any).__metadata[key];
        });

      const result = await guard.canActivate(ctx);
      expect(result).toBe(true);
    });

    it('should allow admin to read dashboard', async () => {
      const ctx = createMockContext({
        metadata: {
          [CASBIN_RESOURCE]: 'dashboard',
          [CASBIN_ACTION]: 'read',
        },
        user: { userId: '1', username: 'admin', role: 'admin' },
      });

      jest
        .spyOn(reflector, 'getAllAndOverride')
        .mockImplementation((key: string) => {
          return (ctx as any).__metadata[key];
        });

      const result = await guard.canActivate(ctx);
      expect(result).toBe(true);
    });

    it('should deny viewer from writing sales-orders', async () => {
      const ctx = createMockContext({
        metadata: {
          [CASBIN_RESOURCE]: 'sales-orders',
          [CASBIN_ACTION]: 'write',
        },
        user: { userId: '2', username: 'viewer', role: 'viewer' },
      });

      jest
        .spyOn(reflector, 'getAllAndOverride')
        .mockImplementation((key: string) => {
          return (ctx as any).__metadata[key];
        });

      await expect(guard.canActivate(ctx)).rejects.toThrow(ForbiddenException);
    });

    // --- New role tests ---

    it('should allow sales role to write customers', async () => {
      const ctx = createMockContext({
        metadata: {
          [CASBIN_RESOURCE]: 'customers',
          [CASBIN_ACTION]: 'write',
        },
        user: { userId: '3', username: 'sales', role: 'sales' },
      });

      jest
        .spyOn(reflector, 'getAllAndOverride')
        .mockImplementation((key: string) => {
          return (ctx as any).__metadata[key];
        });

      const result = await guard.canActivate(ctx);
      expect(result).toBe(true);
    });

    it('should deny sales role from writing suppliers', async () => {
      const ctx = createMockContext({
        metadata: {
          [CASBIN_RESOURCE]: 'suppliers',
          [CASBIN_ACTION]: 'write',
        },
        user: { userId: '3', username: 'sales', role: 'sales' },
      });

      jest
        .spyOn(reflector, 'getAllAndOverride')
        .mockImplementation((key: string) => {
          return (ctx as any).__metadata[key];
        });

      await expect(guard.canActivate(ctx)).rejects.toThrow(ForbiddenException);
    });

    it('should allow warehouse role to write sales-orders (pick/ship)', async () => {
      const ctx = createMockContext({
        metadata: {
          [CASBIN_RESOURCE]: 'sales-orders',
          [CASBIN_ACTION]: 'write',
        },
        user: { userId: '4', username: 'warehouse', role: 'warehouse' },
      });

      jest
        .spyOn(reflector, 'getAllAndOverride')
        .mockImplementation((key: string) => {
          return (ctx as any).__metadata[key];
        });

      const result = await guard.canActivate(ctx);
      expect(result).toBe(true);
    });

    it('should allow procurement role to write suppliers', async () => {
      const ctx = createMockContext({
        metadata: {
          [CASBIN_RESOURCE]: 'suppliers',
          [CASBIN_ACTION]: 'write',
        },
        user: { userId: '5', username: 'procurement', role: 'procurement' },
      });

      jest
        .spyOn(reflector, 'getAllAndOverride')
        .mockImplementation((key: string) => {
          return (ctx as any).__metadata[key];
        });

      const result = await guard.canActivate(ctx);
      expect(result).toBe(true);
    });

    it('should deny procurement role from writing customers', async () => {
      const ctx = createMockContext({
        metadata: {
          [CASBIN_RESOURCE]: 'customers',
          [CASBIN_ACTION]: 'write',
        },
        user: { userId: '5', username: 'procurement', role: 'procurement' },
      });

      jest
        .spyOn(reflector, 'getAllAndOverride')
        .mockImplementation((key: string) => {
          return (ctx as any).__metadata[key];
        });

      await expect(guard.canActivate(ctx)).rejects.toThrow(ForbiddenException);
    });

    it('should allow all roles to read products (inherited from viewer)', async () => {
      for (const role of ['sales', 'warehouse', 'procurement']) {
        const ctx = createMockContext({
          metadata: {
            [CASBIN_RESOURCE]: 'products',
            [CASBIN_ACTION]: 'read',
          },
          user: { userId: '99', username: role, role },
        });

        jest
          .spyOn(reflector, 'getAllAndOverride')
          .mockImplementation((key: string) => {
            return (ctx as any).__metadata[key];
          });

        const result = await guard.canActivate(ctx);
        expect(result).toBe(true);
      }
    });

    describe('Deny-Override logic', () => {
      it('should deny restricted_user from reading dashboard (explicit deny overrides inherited allow)', async () => {
        const ctx = createMockContext({
          metadata: {
            [CASBIN_RESOURCE]: 'dashboard',
            [CASBIN_ACTION]: 'read',
          },
          user: {
            userId: '100',
            username: 'restricted',
            role: 'restricted_user',
          },
        });

        jest
          .spyOn(reflector, 'getAllAndOverride')
          .mockImplementation((key: string) => {
            return (ctx as any).__metadata[key];
          });

        await expect(guard.canActivate(ctx)).rejects.toThrow(
          ForbiddenException,
        );
      });

      it('should allow restricted_user to read products (inherited allow with no explicit deny)', async () => {
        const ctx = createMockContext({
          metadata: {
            [CASBIN_RESOURCE]: 'products',
            [CASBIN_ACTION]: 'read',
          },
          user: {
            userId: '100',
            username: 'restricted',
            role: 'restricted_user',
          },
        });

        jest
          .spyOn(reflector, 'getAllAndOverride')
          .mockImplementation((key: string) => {
            return (ctx as any).__metadata[key];
          });

        const result = await guard.canActivate(ctx);
        expect(result).toBe(true);
      });
    });
  });
});

import { SystemResource } from '@modbm/shared';
import {
  Controller,
  Get,
  Post,
  Param,
  Body,
  UseGuards,
  Req,
  HttpCode,
  Put,
  Delete,
} from '@nestjs/common';
import {
  ApiTags,
  ApiOperation,
  ApiBody,
  ApiOkResponse,
  ApiCreatedResponse,
} from '@nestjs/swagger';
import { AuthGuard } from '@nestjs/passport';
import {
  CasbinGuard,
  CasbinResource,
  CasbinAction,
} from '../auth/casbin.guard';
import {
  CreateBusinessReportDto,
  UpdateBusinessReportDto,
  BusinessReportResponseDto,
} from './business-reports.dto';
import { AuthUser, type JwtUser } from '../auth/auth-user.decorator';
import { BusinessReportsService } from './business-reports.service';

@ApiTags('System')
@Controller('business-reports')
@UseGuards(AuthGuard(['jwt', 'api-key']), CasbinGuard)
@CasbinResource(SystemResource.BUSINESS_REPORT)
export class BusinessReportsController {
  constructor(private readonly service: BusinessReportsService) {}

  @Get()
  @CasbinAction('read')
  @ApiOperation({
    summary: 'List available business reports',
    description: 'Returns a list of available business reports',
  })
  @ApiOkResponse({ type: [Object] }) // BYPASS-TYPING-TEST
  async getReports(@AuthUser() user: JwtUser) {
    return this.service.getReports(user);
  }

  @Get('hooks')
  @CasbinAction('read')
  @ApiOperation({
    summary: 'List available data source hooks',
    description:
      'Returns a list of all registered business report data source hooks',
  })
  @ApiOkResponse({ type: [String] })
  async getHooks() {
    return this.service.getAvailableHooks();
  }

  @Post(':slug/data')
  @HttpCode(200)
  @CasbinAction('read')
  @ApiOperation({
    summary: 'Fetch data for a business report',
    description: 'Returns data for a specific business report',
  })
  @ApiBody({ type: Object }) // BYPASS-TYPING-TEST
  @ApiOkResponse({ type: [Object] }) // BYPASS-TYPING-TEST
  async runReport(
    @Param('slug') slug: string,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    @Body() filters: Record<string, unknown>,
    @AuthUser() user: JwtUser,
  ) {
    const data = await this.service.runReport(slug, filters, user);
    return data;
  }

  @Get(':id')
  @CasbinAction('read')
  @ApiOperation({
    summary: 'Get a business report by ID',
    description: 'Returns the configuration for a specific business report',
  })
  @ApiOkResponse({ type: Object }) // BYPASS-TYPING-TEST
  async getReportById(@Param('id') id: string) {
    return this.service.getReportById(id);
  }

  @Post()
  @CasbinAction('write')
  @ApiOperation({
    summary: 'Create a business report',
    description: 'Creates a new business report configuration',
  })
  @ApiBody({ type: CreateBusinessReportDto })
  @ApiCreatedResponse({ type: BusinessReportResponseDto })
  async createReport(@Body() data: CreateBusinessReportDto) {
    return this.service.createReport(data);
  }

  @Put(':id')
  @CasbinAction('write')
  @ApiOperation({
    summary: 'Update a business report',
    description: 'Updates an existing business report configuration',
  })
  @ApiBody({ type: UpdateBusinessReportDto })
  @ApiOkResponse({ type: BusinessReportResponseDto })
  async updateReport(
    @Param('id') id: string,
    @Body() data: UpdateBusinessReportDto,
  ) {
    return this.service.updateReport(id, data);
  }

  @Delete(':id')
  @CasbinAction('archive')
  @ApiOperation({
    summary: 'Delete a business report',
    description: 'Deletes an existing business report configuration',
  })
  @ApiOkResponse({ type: Object }) // BYPASS-TYPING-TEST
  async deleteReport(@Param('id') id: string) {
    return this.service.deleteReport(id);
  }
}

import { AllExceptionsFilter } from './all-exceptions.filter';
import { HttpException, HttpStatus, Logger } from '@nestjs/common';
import { ArgumentsHost } from '@nestjs/common';

describe('AllExceptionsFilter', () => {
  let filter: AllExceptionsFilter;
  let errorSpy: jest.SpyInstance;
  let warnSpy: jest.SpyInstance;
  let mockResponse: any;
  let mockRequest: any;
  let mockHost: ArgumentsHost;

  beforeEach(() => {
    filter = new AllExceptionsFilter();
    errorSpy = jest.spyOn(Logger.prototype, 'error').mockImplementation();
    warnSpy = jest.spyOn(Logger.prototype, 'warn').mockImplementation();

    mockResponse = {
      status: jest.fn().mockReturnThis(),
      json: jest.fn().mockReturnThis(),
    };
    mockRequest = {
      method: 'GET',
      url: '/api/sales-orders',
    };
    mockHost = {
      switchToHttp: () => ({
        getRequest: () => mockRequest,
        getResponse: () => mockResponse,
      }),
    } as any;
  });

  afterEach(() => {
    errorSpy.mockRestore();
    warnSpy.mockRestore();
  });

  it('should log HttpException (404) as structured JSON via warn', () => {
    const exception = new HttpException('Not Found', HttpStatus.NOT_FOUND);

    filter.catch(exception, mockHost);

    expect(warnSpy).toHaveBeenCalledTimes(1);
    const payload = JSON.parse(warnSpy.mock.calls[0][0]);
    expect(payload.event).toBe('unhandled_exception');
    expect(payload.method).toBe('GET');
    expect(payload.path).toBe('/api/sales-orders');
    expect(payload.statusCode).toBe(404);
    expect(payload.message).toBe('Not Found');

    expect(mockResponse.status).toHaveBeenCalledWith(404);
    expect(mockResponse.json).toHaveBeenCalledWith(
      expect.objectContaining({
        statusCode: 404,
        message: 'Not Found',
        path: '/api/sales-orders',
      }),
    );
  });

  it('should log unknown Error as 500 via error logger', () => {
    const exception = new Error('Database connection lost');

    filter.catch(exception, mockHost);

    expect(errorSpy).toHaveBeenCalledTimes(1);
    const payload = JSON.parse(errorSpy.mock.calls[0][0]);
    expect(payload.event).toBe('unhandled_exception');
    expect(payload.statusCode).toBe(500);
    expect(payload.message).toBe('Database connection lost');
    expect(payload.stack).toBeDefined();

    expect(mockResponse.status).toHaveBeenCalledWith(500);
  });

  it('should handle non-Error throws (string) as 500', () => {
    filter.catch('Something unexpected', mockHost);

    expect(errorSpy).toHaveBeenCalledTimes(1);
    const payload = JSON.parse(errorSpy.mock.calls[0][0]);
    expect(payload.statusCode).toBe(500);
    expect(payload.message).toBe('Something unexpected');
    expect(payload.stack).toBeNull();

    expect(mockResponse.status).toHaveBeenCalledWith(500);
  });

  it('should log HttpException (403) as warn, not error', () => {
    const exception = new HttpException('Forbidden', HttpStatus.FORBIDDEN);

    filter.catch(exception, mockHost);

    expect(warnSpy).toHaveBeenCalledTimes(1);
    expect(errorSpy).not.toHaveBeenCalled();
    expect(mockResponse.status).toHaveBeenCalledWith(403);
  });

  describe('Postgres Error Mapping', () => {
    it('should map Postgres code 23505 to 409 Conflict', () => {
      const error = { code: '23505', detail: 'Key already exists' };
      filter.catch(error, mockHost);

      expect(mockResponse.status).toHaveBeenCalledWith(HttpStatus.CONFLICT);
      expect(mockResponse.json).toHaveBeenCalledWith(
        expect.objectContaining({
          statusCode: 409,
          message: expect.stringContaining('DB Detail: Key already exists'),
        }),
      );
    });

    it('should map Postgres code 23503 to 422 Unprocessable Entity', () => {
      const error = { code: '23503', detail: 'Foreign key violation' };
      filter.catch(error, mockHost);

      expect(mockResponse.status).toHaveBeenCalledWith(
        HttpStatus.UNPROCESSABLE_ENTITY,
      );
    });

    it('should map Postgres code 23514 to 400 Bad Request', () => {
      const error = { code: '23514', detail: 'Check constraint violation' };
      filter.catch(error, mockHost);

      expect(mockResponse.status).toHaveBeenCalledWith(HttpStatus.BAD_REQUEST);
    });
  });
});

import { emitEvent, EmitEventParams } from './emit-event';
import { EntityType, EventType, OUTBOX_EVENT_TYPES } from './event-types';

// ---------------------------------------------------------------------------
// Mock DB transaction — tracks all insert calls for assertion
// ---------------------------------------------------------------------------

interface InsertCall {
  table: any;
  values: any;
}

function createMockTx() {
  const calls: InsertCall[] = [];

  const tx = {
    insert: (table: any) => ({
      values: (vals: any) => {
        calls.push({ table, values: vals });
        return Promise.resolve();
      },
    }),
  };

  return { tx, calls };
}

function createFailingTx(failOnTable?: any) {
  const tx = {
    insert: (table: any) => ({
      values: (_vals: any) => {
        if (!failOnTable || table === failOnTable) {
          return Promise.reject(new Error('DB_INSERT_FAILED'));
        }
        return Promise.resolve();
      },
    }),
  };

  return tx;
}

