import { ConsoleLogger, Injectable } from '@nestjs/common';
import * as fs from 'fs';
import * as path from 'path';

@Injectable()
export class FileLoggerService extends ConsoleLogger {
  private readonly logFilePath: string;

  constructor(context?: string, filename = 'api.log') {
    super(context || 'App');
    const logDir =
      process.env.PIPELINE_LOG_DIR || path.join(process.cwd(), 'logs');
    if (!fs.existsSync(logDir)) {
      try {
        fs.mkdirSync(logDir, { recursive: true });
      } catch {
        // Ignored
      }
    }
    this.logFilePath = path.join(logDir, filename);
  }

  private appendLog(level: string, message: unknown, context?: string) {
    const timestamp = new Date().toISOString();
    const ctx = context || this.context;

    // Attempt to stringify objects securely
    let msgStr = '';
    if (typeof message === 'object') {
      try {
        msgStr = JSON.stringify(message);
      } catch {
        msgStr = String(message);
      }
    } else {
      msgStr = String(message);
    }

    const logLine = `[${timestamp}] [${level.toUpperCase()}] [${ctx}] ${msgStr}\n`;
    try {
      fs.appendFileSync(this.logFilePath, logLine);

      // Rotate if larger than 20MB
      const stats = fs.statSync(this.logFilePath);
      if (stats.size > 20 * 1024 * 1024) {
        const backupPath = `${this.logFilePath}.1`;
        try {
          if (fs.existsSync(backupPath)) {
            fs.unlinkSync(backupPath);
          }
          fs.renameSync(this.logFilePath, backupPath);
        } catch {
          fs.writeFileSync(this.logFilePath, '');
        }
      }
    } catch {
      // Silently fail if file system is inaccessible
    }
  }

  log(message: unknown, context?: string) {
    super.log(message, context);
    this.appendLog('log', message, context);
  }

  error(message: unknown, stack?: string, context?: string) {
    super.error(message, stack, context);
    this.appendLog('error', `${message} ${stack || ''}`, context);
  }

  warn(message: unknown, context?: string) {
    super.warn(message, context);
    this.appendLog('warn', message, context);
  }

  debug(message: unknown, context?: string) {
    super.debug(message, context);
    this.appendLog('debug', message, context);
  }

  verbose(message: unknown, context?: string) {
    super.verbose(message, context);
    this.appendLog('verbose', message, context);
  }
}

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  NestInterceptor,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';

/**
 * Intercepts responses and filters fields based on the `?fields=` query parameter.
 * This is primarily used to optimize payloads for AI agents.
 */
@Injectable()
export class FieldMaskInterceptor implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest();
    const fieldsQuery = request.query.fields;

    if (!fieldsQuery || typeof fieldsQuery !== 'string') {
      return next.handle();
    }

    const requestedFields = new Set(
      fieldsQuery.split(',').map((f) => f.trim()),
    );

    return next.handle().pipe(
      map((data) => {
        return this.filterFields(data, requestedFields);
      }),
    );
  }

  private filterFields(data: unknown, fields: Set<string>): unknown {
    if (data === null || data === undefined) {
      return data;
    }

    if (Array.isArray(data)) {
      return data.map((item) => this.filterFields(item, fields));
    }

    if (typeof data === 'object') {
      // If the response wraps data in pagination or data objects, traverse down
      if (
        'data' in data &&
        Array.isArray((data as Record<string, unknown>).data)
      ) {
        return {
          ...data,
          data: ((data as Record<string, unknown>).data as unknown[]).map(
            (item: unknown) => this.filterFields(item, fields),
          ),
        };
      }

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const filtered: Record<string, unknown> = {};
      for (const [key, value] of Object.entries(data)) {
        if (fields.has(key)) {
          filtered[key] = value;
        }
      }
      return filtered;
    }

    return data;
  }
}

import { withCursorPagination, encodeCursor } from './pagination';

describe('withCursorPagination', () => {
  // Mock Drizzle QueryBuilder
  const createMockQb = (mockRows: any[]) => {
    return {
      limit: jest.fn().mockImplementation(function () {
        return Promise.resolve(mockRows);
      }),
    };
  };

  const applyWhere = jest.fn((q) => q);
  const applyOrderBy = jest.fn((q) => q);
  const encodeRow = (row: any) => ({ id: row.id });

  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should handle the first page (direction: next, no cursor, hasMore: true)', async () => {
    // We request limit=2. The mock returns 3 items (limit + 1)
    const mockRows = [{ id: 1 }, { id: 2 }, { id: 3 }];
    const qb = createMockQb(mockRows);

    const result = await withCursorPagination({
      qb,
      limit: 2,
      cursorObj: null,
      direction: 'next',
      applyWhere,
      applyOrderBy,
      encodeRow,
    });

    expect(result.data).toEqual([{ id: 1 }, { id: 2 }]); // Trims the 3rd item
    expect(result.prevCursor).toBeUndefined(); // First page has no previous page
    expect(result.nextCursor).toBe(encodeCursor({ id: 2 })); // Has next page
  });

  it('should handle a middle page (direction: next, has cursor, hasMore: true)', async () => {
    // We request limit=2. The mock returns 3 items
    const mockRows = [{ id: 3 }, { id: 4 }, { id: 5 }];
    const qb = createMockQb(mockRows);

    const result = await withCursorPagination({
      qb,
      limit: 2,
      cursorObj: { id: 2 },
      direction: 'next',
      applyWhere,
      applyOrderBy,
      encodeRow,
    });

    expect(result.data).toEqual([{ id: 3 }, { id: 4 }]);
    expect(result.prevCursor).toBe(encodeCursor({ id: 3 }));
    expect(result.nextCursor).toBe(encodeCursor({ id: 4 }));
  });

  it('should handle the last page (direction: next, has cursor, hasMore: false)', async () => {
    // We request limit=2. The mock returns 1 item (fewer than limit + 1)
    const mockRows = [{ id: 3 }];
    const qb = createMockQb(mockRows);

    const result = await withCursorPagination({
      qb,
      limit: 2,
      cursorObj: { id: 2 },
      direction: 'next',
      applyWhere,
      applyOrderBy,
      encodeRow,
    });

    expect(result.data).toEqual([{ id: 3 }]);
    expect(result.prevCursor).toBe(encodeCursor({ id: 3 }));
    expect(result.nextCursor).toBeUndefined(); // Last page has no next page
  });

  it('should handle navigating backwards (direction: prev, has cursor, hasMore: true)', async () => {
    // We request limit=2. Query is DESC, so items return in reverse order.
    // E.g., we asked for < 5. DB returns 4, 3, 2. (limit + 1)
    const mockRows = [{ id: 4 }, { id: 3 }, { id: 2 }];
    const qb = createMockQb(mockRows);

    const result = await withCursorPagination({
      qb,
      limit: 2,
      cursorObj: { id: 5 },
      direction: 'prev',
      applyWhere,
      applyOrderBy,
      encodeRow,
    });

    // The data should be reversed to natural order [3, 4]
    expect(result.data).toEqual([{ id: 3 }, { id: 4 }]);
    expect(result.prevCursor).toBe(encodeCursor({ id: 3 })); // There are items before 3 (hasMore was true)
    expect(result.nextCursor).toBe(encodeCursor({ id: 4 }));
  });

  it('should handle reaching the first page backwards (direction: prev, has cursor, hasMore: false)', async () => {
    // We request limit=2. Query is DESC. We asked for < 3.
    // DB returns 2, 1. (Exactly limit, or fewer, meaning no more items before them)
    const mockRows = [{ id: 2 }, { id: 1 }];
    const qb = createMockQb(mockRows);

    const result = await withCursorPagination({
      qb,
      limit: 2,
      cursorObj: { id: 3 },
      direction: 'prev',
      applyWhere,
      applyOrderBy,
      encodeRow,
    });

    // The data should be reversed to natural order [1, 2]
    expect(result.data).toEqual([{ id: 1 }, { id: 2 }]);
    expect(result.prevCursor).toBeUndefined(); // No items before 1 (hasMore was false)
    expect(result.nextCursor).toBe(encodeCursor({ id: 2 }));
  });
});

