import { Injectable } from '@nestjs/common';
import {
  IEnrichmentProvider,
  EnrichmentResult,
} from './enrichment-provider.interface';
import { IntegrationLoggerService } from '../../common/integration-logger.service';

@Injectable()
export class AbrProvider implements IEnrichmentProvider {
  constructor(private readonly logger: IntegrationLoggerService) {
    this.logger.setContext(AbrProvider.name);
  }

  get name(): string {
    return 'abr';
  }

  get type(): 'enrichment' | 'tax_engine' {
    return 'enrichment';
  }

  get supportedCountries(): string[] | 'global' {
    return ['AU'];
  }

  getConfigSchema(): Record<string, unknown> {
    return {
      type: 'object',
      properties: {
        apiKey: { type: 'string', title: 'ABR API GUID', format: 'password' },
        testPayload: {
          type: 'object',
          title: 'Test Payload',
          description: 'A sample payload to test the integration.',
          default: JSON.stringify(
            {
              abn: '51824753556',
            },
            null,
            2,
          ),
        },
      },
    };
  }

  async lookup(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    payload: string | Record<string, unknown>,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    config?: Record<string, unknown>,
  ): Promise<EnrichmentResult> {
    const cleanAbn =
      typeof payload === 'string'
        ? payload.replace(/\s+/g, '')
        : String((payload as Record<string, string>)?.abn || '').replace(
            /\s+/g,
            '',
          );

    if (!config?.apiKey) {
      throw new Error(
        'ABR API key not configured. Please configure it in Settings > Integrations.',
      );
    }

    this.logger.log(`[ABR] Sending lookup request for ABN: ${cleanAbn}`);

    const url = `https://abr.business.gov.au/json/AbnDetails.aspx?abn=${cleanAbn}&guid=${config.apiKey as string}&callback=callback`;

    try {
      const response = await fetch(url);
      if (!response.ok) {
        this.logger.error(
          `[ABR] HTTP Error: ${response.status} ${response.statusText}`,
        );
        return { isValid: false, data: {} };
      }

      const text = await response.text();

      // Strip the JSONP callback wrapper: "callback({...})"
      const jsonString = text.replace(/^callback\(/, '').replace(/\)$/, '');

      const data = JSON.parse(jsonString);

      if (data.Message) {
        this.logger.error(`[ABR] API Error Message: ${data.Message}`);
        return { isValid: false, data: {} };
      }

      const name =
        data.EntityName ||
        (data.BusinessName && data.BusinessName[0]) ||
        'Unknown';
      const isTaxRegistered = !!data.Gst;

      this.logger.log(`[ABR] Successfully retrieved data for ABN: ${cleanAbn}`);

      return {
        isValid: true,
        data: {
          name,
          isTaxRegistered,
        },
      };
    } catch (error) {
      this.logger.error(
        `[ABR] Exception during lookup: ${(error as Error).message}`,
      );
      return { isValid: false, data: {} };
    }
  }
}

export interface EnrichmentResult {
  isValid: boolean;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  data: Record<string, unknown>;
}

export interface IEnrichmentProvider {
  /**
   * The unique identifier for this provider (e.g. 'abr')
   */
  get name(): string;

  /**
   * The type of provider (e.g., 'enrichment', 'tax_engine')
   */
  get type(): 'enrichment' | 'tax_engine';

  /**
   * List of ISO Alpha-2 country codes this provider supports, or 'global' for all.
   */
  get supportedCountries(): string[] | 'global';

  /**
   * Perform a lookup against the external service.
   * @param payload The input string (e.g. business number) or JSON object
   * @param config The provider configuration (e.g. API keys)
   * @returns EnrichmentResult
   */
  lookup(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    payload: string | Record<string, unknown>,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    config?: Record<string, unknown>,
  ): Promise<EnrichmentResult>;

  /**
   * Return the JSON schema defining the required configuration for this provider.
   */
  getConfigSchema(): Record<string, unknown>;

  /**
   * Optional: Record a formal transaction to the provider (for stateful API engines like tax providers)
   */
  recordTransaction?(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    payload: Record<string, unknown>,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    config?: Record<string, unknown>,
  ): Promise<EnrichmentResult>;

  /**
   * Optional: Reverse a previously recorded formal transaction
   */
  recordRefund?(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    payload: Record<string, unknown>,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    config?: Record<string, unknown>,
  ): Promise<EnrichmentResult>;
}

