        '2026-01-01',
        '2026-12-31',
        '50',
      );
      expect(glService.getGeneralLedger).toHaveBeenCalledWith({
        accountCode: '1100',
        fromDate: '2026-01-01',
        toDate: '2026-12-31',
        limit: 50,
      });
