  describe('recordInventoryMovement', () => {
    it('should insert an entry header, ledger lines, and update bin contents', async () => {
      const params = {
        entryNumber: 'MV-001',
        sourceType: 'TEST',
        sourceId: '00000000-0000-0000-0000-000000000e11',
        memo: 'Test movement',
        userId: 'admin',
        lines: [{ productId: PRODUCT_ID, binId: BIN_ID, quantity: 10 }],
      };

      await pg.db.transaction(async (tx) => {
        await service.recordInventoryMovement(tx as any, params);
      });

      // Verify header
      const entries = await pg.db
        .select()
        .from(inventoryEntries)
        .where(eq(inventoryEntries.entryNumber, 'MV-001'));
      expect(entries).toHaveLength(1);
      expect(entries[0].sourceType).toBe('TEST');

      // Verify ledger
      const ledger = await pg.db
        .select()
        .from(inventoryLedger)
        .where(eq(inventoryLedger.entryId, entries[0].entryId));
      expect(ledger).toHaveLength(1);
      expect(ledger[0].quantity).toBe('10');

      // Verify bin contents (cache)
      const bins_data = await pg.db
        .select()
        .from(binContents)
        .where(eq(binContents.binId, BIN_ID));
      expect(bins_data).toHaveLength(1);
      expect(bins_data[0].actualQuantity).toBe('10');

      // Verify event emission
      expect(emitEvent).toHaveBeenCalledWith(
        expect.anything(),
        expect.objectContaining({
          entityType: 'inventory_ledger',
          eventType: 'entry_posted',
        }),
      );
    });

    it('should correctly handle negative quantities (picks)', async () => {
      const params = {
        entryNumber: 'MV-002',
        sourceType: 'PICK',
        sourceId: '00000000-0000-0000-0000-000000000e12',
        lines: [{ productId: PRODUCT_ID, binId: BIN_ID, quantity: -5 }],
      };

      await pg.db.transaction(async (tx) => {
        await service.recordInventoryMovement(tx as any, params);
      });

      const bins_data = await pg.db
        .select()
        .from(binContents)
        .where(eq(binContents.binId, BIN_ID));
      expect(bins_data).toHaveLength(0);
    });
  });

  describe('moveStock', () => {
    it('should emit stock_moved and entry_posted events', async () => {
      // Seed target bin
      const TARGET_BIN_ID = '00000000-0000-0000-0000-000000000010';
      await pg.db.insert(bins).values({
        binId: TARGET_BIN_ID,
        zoneId: ZONE_ID,
        binNumber: 'B-01-02',
      });

      // Seed initial stock
      await pg.db.insert(binContents).values({
        binId: BIN_ID,
        productId: PRODUCT_ID,
        actualQuantity: '100',
      });

      const params = {
        lines: [
          {
            productId: PRODUCT_ID,
            sourceBinId: BIN_ID,
            targetBinId: TARGET_BIN_ID,
            quantity: '10',
          },
        ],
        reason: 'Consolidation',
      };

      await service.moveStock(params as any, 'admin');

      // Verify emitEvent called at least twice (one for ledger, one for warehouse)
      expect(emitEvent).toHaveBeenCalledWith(
        expect.anything(),
        expect.objectContaining({
          entityType: 'warehouse',
          eventType: 'stock_moved',
        }),
      );

      expect(emitEvent).toHaveBeenCalledWith(
        expect.anything(),
        expect.objectContaining({
          entityType: 'inventory_ledger',
          eventType: 'entry_posted',
        }),
      );

      // Check cache updated
      const sourceBin = await pg.db
        .select()
        .from(binContents)
        .where(eq(binContents.binId, BIN_ID));
      expect(sourceBin[0].actualQuantity).toBe('90');

      const targetBin = await pg.db
        .select()
        .from(binContents)
        .where(eq(binContents.binId, TARGET_BIN_ID));
      expect(targetBin[0].actualQuantity).toBe('10');
    });
  });

  describe('quarantineMove', () => {
    it('should emit stock_moved and entry_posted events', async () => {
      // Seed target bin
      const TARGET_BIN_ID = '00000000-0000-0000-0000-000000000011';
      await pg.db.insert(bins).values({
        binId: TARGET_BIN_ID,
        zoneId: ZONE_ID,
        binNumber: 'QUARANTINE-1',
        binType: 'quarantine',
      });

      // Seed initial stock
      await pg.db.insert(binContents).values({
        binId: BIN_ID,
        productId: PRODUCT_ID,
        actualQuantity: '100',
      });

      await service.quarantineStock(
        {
          productId: PRODUCT_ID,
          sourceBinId: BIN_ID,
          targetBinId: TARGET_BIN_ID,
          quantity: '5',
          reason: 'Damaged',
        },
        'admin',
      );

      expect(emitEvent).toHaveBeenCalledWith(
        expect.anything(),
        expect.objectContaining({
          entityType: 'warehouse',
          eventType: 'stock_moved',
        }),
      );

      expect(emitEvent).toHaveBeenCalledWith(
        expect.anything(),
        expect.objectContaining({
          entityType: 'inventory_ledger',
          eventType: 'entry_posted',
        }),
      );
    });
  });

  describe('findAll', () => {
    it('should return paginated inventory levels', async () => {
      // Seed some ledger data to have non-zero stock
      const entryId = '00000000-0000-0000-0000-0000000000e1';
      await pg.db.insert(inventoryEntries).values({
        entryId,
        entryNumber: 'E1',
        sourceType: 'INIT',
        entryDate: new Date(),
      });
      await pg.db.insert(inventoryLedger).values({
        entryId,
        productId: PRODUCT_ID,
        locationId: LOCATION_ID,
        binId: BIN_ID,
        zoneId: ZONE_ID,
        quantity: '100',
      });
      await pg.db.insert(binContents).values({
        binId: BIN_ID,
        productId: PRODUCT_ID,
        actualQuantity: '100',
      });

      const result = await service.findAll();
      expect(result.data).toHaveLength(1);
      expect(result.data[0].productNumber).toBe('P1');
      expect(result.data[0].quantityAvailable).toBe(100);
    });
  });

  describe('findAllLocations', () => {
    it('omits availableQty when no productId is supplied', async () => {
      const result = await service.findAllLocations();
      expect(result.length).toBeGreaterThan(0);
      for (const loc of result) {
        expect((loc as any).availableQty).toBeUndefined();
      }
    });

    it('returns availableQty per location when productId is supplied', async () => {
      // Seed some stock so the inventory_levels view has rows
      const entryId = '00000000-0000-0000-0000-0000000000f1';
      await pg.db.insert(inventoryEntries).values({
        entryId,
        entryNumber: 'E-LOC-1',
        sourceType: 'INIT',
        entryDate: new Date(),
      });
      await pg.db.insert(inventoryLedger).values({
        entryId,
        productId: PRODUCT_ID,
        locationId: LOCATION_ID,
        binId: BIN_ID,
        zoneId: ZONE_ID,
        quantity: '42',
      });
      await pg.db.insert(binContents).values({
        binId: BIN_ID,
        productId: PRODUCT_ID,
        actualQuantity: '42',
      });

      const result = await service.findAllLocations(PRODUCT_ID);
      const main = (result as any[]).find((l) => l.locationId === LOCATION_ID);
      expect(main).toBeDefined();
      expect(main.availableQty).toBe(42);
    });

    it('returns 0 availableQty for locations with no stock of the product', async () => {
      const result = await service.findAllLocations(PRODUCT_ID);
      // The seeded LOCATION_ID has nothing in bin_contents for this product
      const main = (result as any[]).find((l) => l.locationId === LOCATION_ID);
      expect(main).toBeDefined();
      expect(main.availableQty).toBe(0);
    });
  });
});

import { Test, TestingModule } from '@nestjs/testing';
import {
  SalesInvoiceController,
  PurchaseInvoiceController,
  InvoiceDetailController,
} from './invoices.controller';
import { SalesInvoiceService } from './sales-invoice.service';
import { PurchaseInvoiceService } from './purchase-invoice.service';

describe('Invoices Controllers', () => {
  let salesController: SalesInvoiceController;
  let purchaseController: PurchaseInvoiceController;
  let detailController: InvoiceDetailController;

  let mockSalesService: any;
  let mockPurchaseService: any;

  beforeEach(async () => {
    mockSalesService = {
      createInvoice: jest.fn().mockResolvedValue({ id: 'si-1' }),
      findByOrder: jest.fn().mockResolvedValue([{ id: 'si-1' }]),
      findOne: jest.fn().mockResolvedValue({ id: 'si-1', total: 100 }),
      findActiveInvoices: jest.fn().mockResolvedValue([{ id: 'si-1' }]),
    };

    mockPurchaseService = {
      findByOrder: jest.fn().mockResolvedValue([{ id: 'pi-1' }]),
      findOne: jest.fn().mockResolvedValue({ id: 'pi-1', total: 200 }),
    };

    const module: TestingModule = await Test.createTestingModule({
      controllers: [
        SalesInvoiceController,
        PurchaseInvoiceController,
        InvoiceDetailController,
      ],
      providers: [
        { provide: SalesInvoiceService, useValue: mockSalesService },
        { provide: PurchaseInvoiceService, useValue: mockPurchaseService },
      ],
    }).compile();

    salesController = module.get<SalesInvoiceController>(
      SalesInvoiceController,
    );
    purchaseController = module.get<PurchaseInvoiceController>(
      PurchaseInvoiceController,
    );
    detailController = module.get<InvoiceDetailController>(
      InvoiceDetailController,
    );
  });

  describe('SalesInvoiceController', () => {
    it('should create a sales invoice', async () => {
      const dto: any = { lines: [] };
      const req = { user: { username: 'test-user' } };

      const result = await salesController.createSalesInvoice(
        'order-1',
        dto,
        req,
      );

      expect(result).toEqual({ id: 'si-1' });
      expect(mockSalesService.createInvoice).toHaveBeenCalledWith(
        'order-1',
        dto,
        'test-user',
      );
    });

    it('should create a sales invoice with fallback actor if user missing', async () => {
      const result = await salesController.createSalesInvoice(
        'order-1',
        {} as any,
        {},
      );
      expect(mockSalesService.createInvoice).toHaveBeenCalledWith(
        'order-1',
        {},
        'system',
      );
    });

    it('should get sales invoices by order ID', async () => {
      const result = await salesController.getSalesInvoices('order-1');
      expect(result).toEqual([{ id: 'si-1' }]);
      expect(mockSalesService.findByOrder).toHaveBeenCalledWith('order-1');
    });
  });

  describe('PurchaseInvoiceController', () => {
    it('should get purchase bills by order ID', async () => {
      const result = await purchaseController.getPurchaseBills('p-order-1');
      expect(result).toEqual([{ id: 'pi-1' }]);
      expect(mockPurchaseService.findByOrder).toHaveBeenCalledWith('p-order-1');
    });
  });

  describe('InvoiceDetailController', () => {
    it('should get sales invoice details by ID', async () => {
      const result = await detailController.getSalesInvoiceDetails('si-1');
      expect(result).toEqual({ id: 'si-1', total: 100 });
      expect(mockSalesService.findOne).toHaveBeenCalledWith('si-1');
    });

    it('should get global active sales invoices with parsed queries', async () => {
      const result = await detailController.getSalesInvoicesGlobal(
        '30',
        'acc-1',
        'inv-1',
        undefined,
        '50',
      );

      expect(result).toEqual([{ id: 'si-1' }]);
      expect(mockSalesService.findActiveInvoices).toHaveBeenCalledWith({
        days: 30,
        customerId: 'acc-1',
        invoiceId: 'inv-1',
        limit: 50,
      });
    });

    it('should get global active sales invoices without queries', async () => {
      const result = await detailController.getSalesInvoicesGlobal();

      expect(result).toEqual([{ id: 'si-1' }]);
      expect(mockSalesService.findActiveInvoices).toHaveBeenCalledWith({
        days: undefined,
        customerId: undefined,
        invoiceId: undefined,
        limit: undefined,
      });
    });

    it('should get purchase bill details by ID', async () => {
      const result = await detailController.getPurchaseBillDetails('pi-1');
      expect(result).toEqual({ id: 'pi-1', total: 200 });
      expect(mockPurchaseService.findOne).toHaveBeenCalledWith('pi-1');
    });
  });
});

import { SystemResource } from '@modbm/shared';
