        .insert(bins)
        .values({ zoneId: zone.zoneId, binNumber: 'B1', binType: 'storage' });

      await expect(service.deleteZone(zone.zoneId)).rejects.toThrow(
        BadRequestException,
      );
    });
  });

  describe('Bins', () => {
    it('should create a bin', async () => {
      const [loc] = await pg.db
        .insert(locations)
        .values({ code: 'L1', name: 'L1' })
        .returning();
