    it('should prevent deleting bin with stock', async () => {
      const [loc] = await pg.db
        .insert(locations)
        .values({ code: 'L1', name: 'L1' })
        .returning();
      const [zone] = await pg.db
        .insert(zones)
        .values({ locationId: loc.locationId, code: 'Z1', name: 'Z1' })
        .returning();
