    it('should reject updating a cancelled shipment', async () => {
      await pg.db
        .update(salesOrderShipments)
        .set({ stateCode: SHIPMENT_STATE.CANCELLED })
        .where(
          eq(
            salesOrderShipments.shipmentId,
            'e0000000-0000-0000-0000-000000000001',
