  async getCsvMetadata() {
    const excludedColumns = [
      'created_by',
      'created_on',
      'modified_on',
      'updated_on',
    ];

    return this.csvRegistry.map((t) => {
      const cols = getTableColumns(t.table);
      const columns = Object.keys(cols)
        .map((k) => {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          const col = (cols as any)[k];
          return {
            name: col.name,
            notNull: col.notNull,
            hasDefault: col.hasDefault,
          };
        })
        .filter((c) => !excludedColumns.includes(c.name))
        .map((c) => {
          const isRequired = c.notNull && !c.hasDefault;
          return isRequired ? `${c.name}*` : c.name;
        });

      return {
        id: t.id,
        name: t.name,
        uniqueKey: t.uniqueKey,
        columns,
      };
    });
  }

  async executeCsv(
    tableName: string,
    strategy: string,
    file: Express.Multer.File,
  ) {
    const registryEntry = this.csvRegistry.find((r) => r.id === tableName);
    if (!registryEntry) throw new BadRequestException('Unsupported table');

    const runningJobId = Object.keys(this.activeJobs).find(
      (id) => this.activeJobs[id].status === 'running',
    );
    if (runningJobId) throw new BadRequestException('A job is already running');

    const jobId = Math.random().toString(36).substring(7);
    this.activeJobs[jobId] = {
      status: 'running',
      progress: [
        { step: 1, name: `Importing CSV to ${tableName}`, status: 'running' },
      ],
      logs: [`--- Initializing CSV Import for ${tableName} ---`],
    };

    this.runCsvCore(registryEntry, strategy, file, jobId).catch((err) => {
      this.logger.error(`CSV job ${jobId} failed`, err);
      this.log(jobId, `FATAL: CSV Import failed: ${err.message}`, 'error');
      if (this.activeJobs[jobId]) {
        this.activeJobs[jobId].status = 'failed';
        this.activeJobs[jobId].progress[0].status = 'failed';
      }
    });

    return { jobId };
  }

  private async runCsvCore(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    entry: any,
    strategy: string,
    file: Express.Multer.File,
    jobId: string,
  ) {
    const mapCurrencyCode = (val: string | null): string | null => {
      if (!val) return null;
      const up = val.toUpperCase().trim();
      if (up === 'AU') return 'AUD'; // HOME_CURRENCY
      if (up === 'US') return 'USD'; // HOME_CURRENCY
      if (up === 'GB') return 'GBP'; // HOME_CURRENCY
      if (up === 'EU') return 'EUR'; // HOME_CURRENCY
      if (up === 'NZ') return 'NZD'; // HOME_CURRENCY
      return val;
    };

    const tableCols = getTableColumns(entry.table);
    const colNames = Object.keys(tableCols).map((k) => tableCols[k].name);

    this.log(jobId, `Starting CSV parsing for strategy: ${strategy}...`);

    const records: Record<string, unknown>[] = [];
    const parser = Readable.from(file.buffer).pipe(
      parse({
        columns: (header: string[]) => header.map((h) => h.replace(/\*$/, '')),
        skip_empty_lines: true,
        trim: true,
      }),
    );

    let parsedCount = 0;
    for await (const record of parser) {
      // Map back to db columns, stripping unknown columns and casting empty strings to null for text fields
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const dbRecord: any = {};
      for (const col of colNames) {
        if (record[col] !== undefined) {
          dbRecord[col] = record[col] === '' ? null : record[col];
          if (col === 'address1Country' && dbRecord[col]) {
            dbRecord[col] = getCountryCode(dbRecord[col]) || dbRecord[col];
          }
          if (col === 'currencyCode') {
            dbRecord[col] = mapCurrencyCode(dbRecord[col]);
          }
        }
      }
      records.push(dbRecord);
      parsedCount++;
      if (parsedCount % 1000 === 0) {
        this.log(jobId, `Parsed ${parsedCount} rows...`);
      }
    }

    this.log(
      jobId,
      `Completed parsing. Total rows: ${records.length}. Starting DB insertion...`,
    );

    // Batch insert
    const BATCH_SIZE = 500;
    let insertedCount = 0;

    for (let i = 0; i < records.length; i += BATCH_SIZE) {
      const batch = records.slice(i, i + BATCH_SIZE);

      if (strategy === 'upsert') {
        const conflictTarget =
          entry.table[entry.uniqueKey] ||
          tableCols[
            Object.keys(tableCols).find(
              (k) => tableCols[k].name === entry.uniqueKey,
            )!
          ];

        // Build set object for DO UPDATE
        const updateSet: Record<string, unknown> = {};
        for (const colName of colNames) {
          if (colName !== entry.uniqueKey) {
            updateSet[colName] = sql.raw(`EXCLUDED.${colName}`);
          }
        }

        await this.db.insert(entry.table).values(batch).onConflictDoUpdate({
          target: conflictTarget,
          set: updateSet,
        });
      } else if (strategy === 'ignore') {
        const conflictTarget =
          entry.table[entry.uniqueKey] ||
          tableCols[
            Object.keys(tableCols).find(
              (k) => tableCols[k].name === entry.uniqueKey,
            )!
          ];
        await this.db.insert(entry.table).values(batch).onConflictDoNothing({
          target: conflictTarget,
        });
      } else {
        await this.db.insert(entry.table).values(batch);
      }

      insertedCount += batch.length;
      this.log(
        jobId,
        `Inserted/Upserted ${insertedCount} / ${records.length} rows...`,
      );
    }

    this.log(jobId, 'DATA IMPORT COMPLETED SUCCESSFULLY');
    if (this.activeJobs[jobId]) {
      this.activeJobs[jobId].progress[0].status = 'done';
      this.activeJobs[jobId].status = 'done';
    }
  }

  private log(
    jobId: string | undefined,
    message: string,
    level: 'log' | 'warn' | 'error' = 'log',
  ) {
    this.logger[level](message);
    if (jobId && this.activeJobs[jobId]) {
      this.activeJobs[jobId].logs.push(message);
    }
  }

  async executeElt(dto: ExecuteEltDto) {
    const runningJobId = Object.keys(this.activeJobs).find(
      (id) => this.activeJobs[id].status === 'running',
    );
    if (runningJobId) return { jobId: runningJobId };

    const jobId = Math.random().toString(36).substring(7);
    this.activeJobs[jobId] = {
      status: 'running',
      progress: [{ step: 1, name: 'Importing Data (ELT)', status: 'running' }],
      logs: [],
    };

    this.runEltCore(dto, jobId).catch((err) => {
      this.logger.error(`ELT job ${jobId} failed`, err);
      if (this.activeJobs[jobId]) {
        this.activeJobs[jobId].status = 'failed';
        this.activeJobs[jobId].progress[0].status = 'failed';
      }
    });

    return { jobId };
  }

  async runEltCore(dto: ExecuteEltDto, jobId?: string) {
    try {
      this.log(jobId, '--- Initializing ABM ELT Pipeline ---');

      if (dto.baseCurrency) {
        this.log(jobId, `Setting base currency to ${dto.baseCurrency}`);
        await this.db
          .update(glSettings)
          .set({ baseCurrency: dto.baseCurrency });
      }

      const [appSettingsRow] = await this.db
        .select()
        .from(appSettings)
        .limit(1);
      let defaultLocationCode = 'HQ';
      let inventoryValuationMethod = 'weighted_average';

      if (appSettingsRow) {
        if (appSettingsRow.inventoryValuationMethod) {
          inventoryValuationMethod = appSettingsRow.inventoryValuationMethod;
        }
        if (appSettingsRow.defaultFulfillmentLocationId) {
          const [loc] = await this.db
            .select()
            .from(locations)
            .where(
              eq(
                locations.locationId,
                appSettingsRow.defaultFulfillmentLocationId,
              ),
            )
            .limit(1);
          if (loc) {
            defaultLocationCode = loc.code;
          }
        }
      }

      const envOverride: Record<string, string> = {
        DEFAULT_FULFILLMENT_LOCATION_CODE:
          dto.defaultLocationCode || defaultLocationCode,
        INVENTORY_VALUATION_METHOD: inventoryValuationMethod,
      };

      if (dto.defaultTaxCategoryCode) {
        envOverride.DEFAULT_TAX_CATEGORY_CODE = dto.defaultTaxCategoryCode;
      }

      if (dto.enableCustomImports) {
        envOverride.ENABLE_CUSTOM_IMPORTS = 'true';
      }

      const isOdoo = dto.odooImport === true;
      const prefix = isOdoo ? 'ODOO_PG' : 'ABM_MSSQL';

      if (dto.dbConfig) {
        if (dto.dbConfig.host)
          envOverride[`${prefix}_HOST`] = dto.dbConfig.host;
        if (dto.dbConfig.database)
          envOverride[`${prefix}_DATABASE`] = dto.dbConfig.database;
        if (dto.dbConfig.username)
          envOverride[`${prefix}_USER`] = dto.dbConfig.username;
        if (dto.dbConfig.password)
          envOverride[`${prefix}_PASSWORD`] = dto.dbConfig.password;
        if (dto.dbConfig.port)
          envOverride[`${prefix}_PORT`] = dto.dbConfig.port.toString();
      }

      envOverride[isOdoo ? 'ODOO_RESUME' : 'ABM_RESUME'] = dto.resumeExtraction
        ? 'true'
        : 'false';

      if (!dto.skipExtraction) {
        const venvPython =
          process.platform === 'win32'
            ? '".venv\\Scripts\\python"'
            : '".venv/bin/python"';
        this.log(
          jobId,
          `Running ${isOdoo ? 'Odoo' : 'ABM'} Extraction (bypassing make to preserve passwords)...`,
        );
        await this.runCommandStream(
          jobId,
          venvPython,
          [`pipelines/${isOdoo ? 'odoo' : 'abm'}_extract/pipeline.py`],
          envOverride,
        );
      } else {
        this.log(jobId, `Skipping ${isOdoo ? 'Odoo' : 'ABM'} Extraction...`);
      }

      this.log(jobId, 'Running Transformations & Report...');
      await this.runCommandStream(
        jobId,
        'make',
        [isOdoo ? 'elt-odoo-no-extract' : 'elt-no-extract'],
        envOverride,
      );

      if (dto.defaultLocationCode) {
        const [loc] = await this.db
          .select()
          .from(locations)
          .where(eq(locations.code, dto.defaultLocationCode))
          .limit(1);
        if (loc) {
          const [existingApp] = await this.db
            .select()
            .from(appSettings)
            .limit(1);
          if (existingApp) {
            await this.db
              .update(appSettings)
              .set({ defaultFulfillmentLocationId: loc.locationId })
              .where(eq(appSettings.settingsId, existingApp.settingsId));
          }
        }
      }

      await this.inferAndSaveGlMetadataSchema(jobId);

      // Reload app config cache so API picks up the new settings
      try {
        await this.appConfig.reload();
      } catch (e: unknown) {
        this.log(
          jobId,
          `Warning: Failed to reload app config cache: ${getErrorMessage(e)}`,
          'error',
        );
      }

      this.log(jobId, 'DATA IMPORT COMPLETED SUCCESSFULLY');
      if (jobId && this.activeJobs[jobId]) {
        this.activeJobs[jobId].progress[0].status = 'done';
        this.activeJobs[jobId].status = 'done';
      }
    } catch (error) {
      this.log(jobId, `FATAL: ELT Import failed: ${error.message}`, 'error');
      if (jobId && this.activeJobs[jobId]) {
        this.activeJobs[jobId].status = 'failed';
        this.activeJobs[jobId].progress[0].status = 'failed';
      }
      throw error;
    }
  }

  getJobProgress(jobId: string) {
    const job = this.activeJobs[jobId];
    if (!job) throw new BadRequestException('Job not found');
    return job;
  }

  private updateJobProgress(
    jobId: string | undefined,
    stepIndex: number,
    status: string,
  ) {
    if (
      jobId &&
      this.activeJobs[jobId] &&
      this.activeJobs[jobId].progress[stepIndex]
    ) {
      this.activeJobs[jobId].progress[stepIndex].status = status;
    }
  }

  private getWorkspaceRoot(): string {
    let currentDir = __dirname;
    while (currentDir !== path.parse(currentDir).root) {
      if (fs.existsSync(path.join(currentDir, 'Makefile'))) return currentDir;
      currentDir = path.dirname(currentDir);
    }
    return process.cwd();
  }

  private runCommandStream(
    jobId: string | undefined,
    cmd: string,
    args: string[],
    envOverride?: Record<string, string>,
  ): Promise<void> {
    return new Promise((resolve, reject) => {
      const child = spawn([cmd, ...args].join(' '), {
        cwd: this.getWorkspaceRoot(),
        shell: true,
        env: { ...process.env, ...envOverride },
      });
      child.stdout.on('data', (data) =>
        this.log(jobId, data.toString().trim()),
      );
      child.stderr.on('data', (data) =>
        this.log(jobId, data.toString().trim()),
      );
      child.on('close', (code) =>
        code === 0
          ? resolve()
          : reject(new Error(`${cmd} failed with code ${code}`)),
      );
    });
  }

  private async inferAndSaveGlMetadataSchema(jobId?: string) {
    this.log(
      jobId,
      'Dynamically inferring GL metadata schema from imported accounts...',
    );
    try {
      const accounts = await this.db
        .select({ metadata: glAccounts.metadata })
        .from(glAccounts)
        .where(isNotNull(glAccounts.metadata));

      const properties: Record<string, { type: string; title: string }> = {};
      for (const acct of accounts) {
        if (
          acct.metadata &&
          typeof acct.metadata === 'object' &&
          !Array.isArray(acct.metadata)
        ) {
          for (const [key, value] of Object.entries(acct.metadata)) {
            if (!properties[key] && value !== null && value !== undefined) {
              const type = typeof value;
              const title = key
                .replace(/([A-Z])/g, ' $1')
                .replace(/^./, (str) => str.toUpperCase());

              properties[key] = {
                type: type === 'number' || type === 'boolean' ? type : 'string',
                title,
              };
            }
          }
        }
      }

      if (Object.keys(properties).length > 0) {
        const [existingGl] = await this.db.select().from(glSettings).limit(1);
        if (existingGl) {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          const existingSchema = (existingGl.accountMetadataSchema as any) || {
            type: 'object',
            properties: {},
          };
          const mergedProperties = {
            ...(existingSchema.properties || {}),
            ...properties,
          };

          await this.db
            .update(glSettings)
            .set({
              accountMetadataSchema: {
                type: 'object',
                properties: mergedProperties,
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
              } as any,
            })
            .where(eq(glSettings.settingsId, existingGl.settingsId));

          this.log(
            jobId,
            `Inferred schema with ${Object.keys(properties).length} properties.`,
          );
        }
      } else {
        this.log(jobId, 'No metadata found to infer schema.');
      }
    } catch (e: unknown) {
      this.log(
        jobId,
        `Warning: Failed to infer metadata schema: ${getErrorMessage(e)}`,
        'error',
      );
    }
  }
}

import {
  Injectable,
  Inject,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import {
  IsString,
  IsNotEmpty,
  IsOptional,
  IsBoolean,
  IsIn,
} from 'class-validator';
import { eq, ne, and } from 'drizzle-orm';
import { DRIZZLE } from '../drizzle/drizzle.module';
import type { DrizzleDB } from '../drizzle/drizzle.module';
import { taxCategories } from '../drizzle/modbm-core-schema';
import { CreateTaxCategoryDto, UpdateTaxCategoryDto } from './dto';

@Injectable()
export class TaxCategoriesService {
  constructor(@Inject(DRIZZLE) private db: DrizzleDB) {}

  async findAll() {
    return this.db.select().from(taxCategories);
  }

  async getById(id: string, tx?: DrizzleDB) {
    const db = tx || this.db;
    const isUuid =
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
        id,
      );
    if (!isUuid) {
      throw new NotFoundException(`Invalid tax category ID: ${id}`);
    }

    const rows = await db
      .select()
      .from(taxCategories)
      .where(eq(taxCategories.taxCategoryId, id))
      .limit(1);
    if (rows.length === 0) {
      throw new NotFoundException(`Tax category '${id}' not found`);
    }
    return rows[0];
  }

  async getDefault(tx?: DrizzleDB) {
    const db = tx || this.db;
    const rows = await db
      .select()
      .from(taxCategories)
      .where(eq(taxCategories.isDefault, true))
      .limit(1);
    if (rows.length === 0) {
      throw new NotFoundException('No default tax category configured');
    }
    return rows[0];
  }

  async getByCode(code: string, tx?: DrizzleDB) {
    const db = tx || this.db;
    const rows = await db
      .select()
      .from(taxCategories)
      .where(eq(taxCategories.code, code))
      .limit(1);
    if (rows.length === 0) {
      throw new NotFoundException(`Tax category code '${code}' not found`);
    }
    return rows[0];
  }

  async create(dto: CreateTaxCategoryDto) {
    // If the new category wants to be default, unset any existing default first
    if (dto.isDefault) {
      await this.db
        .update(taxCategories)
        .set({ isDefault: false })
        .where(eq(taxCategories.isDefault, true));
    }

    const rows = await this.db
      .insert(taxCategories)
      .values({
        code: dto.code,
        title: dto.title,
        type: dto.type,
        rate: dto.rate ?? '0',
        isDefault: dto.isDefault ?? false,
      })
      .returning();
    return rows[0];
  }

  async update(id: string, dto: UpdateTaxCategoryDto) {
    await this.getById(id); // ensure exists

    // If toggling isDefault to true, unset the current default
    if (dto.isDefault === true) {
      await this.db
        .update(taxCategories)
        .set({ isDefault: false })
        .where(
          and(
            eq(taxCategories.isDefault, true),
            ne(taxCategories.taxCategoryId, id),
          ),
        );
    }

    const rows = await this.db
      .update(taxCategories)
      .set({
        ...(dto.code !== undefined && { code: dto.code }),
        ...(dto.title !== undefined && { title: dto.title }),
        ...(dto.type !== undefined && { type: dto.type }),
        ...(dto.rate !== undefined && { rate: dto.rate }),
        ...(dto.isDefault !== undefined && { isDefault: dto.isDefault }),
      })
      .where(eq(taxCategories.taxCategoryId, id))
      .returning();

    return rows[0];
  }

  async delete(id: string) {
    const cat = await this.getById(id);

    if (cat.isDefault) {
      throw new BadRequestException(
        'Cannot delete the default tax category. Assign a different default first.',
      );
    }

    try {
      await this.db
        .delete(taxCategories)
        .where(eq(taxCategories.taxCategoryId, id));
      return { deleted: true };
    } catch (err: unknown) {
      // Postgres foreign_key_violation
      if ((err as any)?.code === '23503') {
        throw new BadRequestException(
          'Cannot delete this tax category because it is assigned to one or more customers or products. Remove the assignments first.',
        );
      }
      throw err;
    }
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { TelemetryController } from './telemetry.controller';
import { Logger, BadRequestException } from '@nestjs/common';
import { ThrottlerModule } from '@nestjs/throttler';

describe('TelemetryController', () => {
  let controller: TelemetryController;
  let warnSpy: jest.SpyInstance;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      imports: [ThrottlerModule.forRoot([{ ttl: 60000, limit: 10 }])],
      controllers: [TelemetryController],
    }).compile();

    controller = module.get<TelemetryController>(TelemetryController);
    warnSpy = jest.spyOn(Logger.prototype, 'warn').mockImplementation();
  });

  afterEach(() => {
    warnSpy.mockRestore();
  });

  it('should log a structured client error and return void (204)', () => {
    const dto = {
      message: 'Not authenticated',
      stack: 'Error: Not authenticated\n    at apiFetch',
      component: 'OrdersPage',
      url: 'http://localhost:4300/',
    };

    const result = controller.reportClientError(dto);

    expect(result).toBeUndefined();
    expect(warnSpy).toHaveBeenCalledTimes(1);
    const loggedPayload = JSON.parse(warnSpy.mock.calls[0][0]);
    expect(loggedPayload).toEqual({
      event: 'client_error',
      message: 'Not authenticated',
      stack: dto.stack,
      component: 'OrdersPage',
      url: 'http://localhost:4300/',
    });
  });

  it('should handle minimal payload (message only)', () => {
    controller.reportClientError({ message: 'Something broke' });

    const loggedPayload = JSON.parse(warnSpy.mock.calls[0][0]);
    expect(loggedPayload.event).toBe('client_error');
    expect(loggedPayload.message).toBe('Something broke');
    expect(loggedPayload.stack).toBeNull();
    expect(loggedPayload.component).toBeNull();
    expect(loggedPayload.url).toBeNull();
  });

  it('should throw BadRequestException when message is missing', () => {
    expect(() => controller.reportClientError({} as any)).toThrow(
      BadRequestException,
    );
  });

  it('should throw BadRequestException when body is null', () => {
    expect(() => controller.reportClientError(null as any)).toThrow(
      BadRequestException,
    );
  });
});

import { beforeAll, beforeEach, afterEach, afterAll } from '@jest/globals';
import * as fs from 'fs';
import * as path from 'path';
import { createMemoryDb } from '../../test/utils/memory-db';
import type { DrizzleDB } from '../drizzle/drizzle.module';
import { PGlite } from '@electric-sql/pglite';
import { drizzle } from 'drizzle-orm/pglite';
import * as schema from '../drizzle/modbm-core-schema';

export interface PgliteTestContext {
  readonly db: DrizzleDB;
  readonly client: PGlite;
}

// --------------------------------------------------------------------------
// Transactional tables that hold test-produced data and must be cleared
// between tests. Reference/seed tables (uom_dictionary, tax_categories,
// gl_accounts, locations, zones, bins, users, etc.) are left intact.
// Order matters — children before parents to respect FK constraints.
// --------------------------------------------------------------------------
const TRANSACTIONAL_TABLES = [
  'modbm_core.gl_journal_lines',
  'modbm_core.gl_journal_entries',
  'modbm_core.sales_invoice_lines',
  'modbm_core.sales_invoices',
  'modbm_core.purchase_invoice_lines',
  'modbm_core.purchase_invoices',
  'modbm_core.sales_order_return_lines',
  'modbm_core.sales_order_returns',
  'modbm_core.sales_order_picks',
  'modbm_core.sales_order_shipment_lines',
  'modbm_core.sales_order_shipments',
  'modbm_core.backorders',
  'modbm_core.order_events',
  'modbm_core.outbox',
  'modbm_core.sales_order_lines',
  'modbm_core.sales_orders',
  'modbm_core.purchase_order_return_lines',
  'modbm_core.purchase_order_returns',
  'modbm_core.goods_received_lines',
  'modbm_core.goods_received',
  'modbm_core.purchase_order_events',
  'modbm_core.purchase_order_lines',
  'modbm_core.purchase_orders',
  'modbm_core.inventory_ledger',
  'modbm_core.account_events',
  'modbm_core.customers',
  'modbm_core.suppliers',
  'modbm_core.products',
  'modbm_core.payment_events',
  'modbm_core.payment_allocations',
  'modbm_core.payment_entries',
];

/**
 * Reusable utility for PGLite testing in NestJS services.
 *
 * Performance strategy: boot PGlite **once** per suite (in beforeAll)
 * from the pre-built snapshot. Between tests, truncate only the
 * transactional tables while keeping seed/reference data intact.
 *
 * This avoids the ~500ms cost of loading a snapshot for each of the
 * 488 test cases — cutting overall suite time roughly in half.
 *
 * For suites with `skipSeeds: true`, the old per-test snapshot reload
 * is used since those suites insert their own reference data.
 */
export function setupPgliteSuite(opts?: {
  skipSeeds?: boolean;
}): PgliteTestContext {
  if (typeof jest !== 'undefined') {
    jest.setTimeout(30000);
  }
  const context = {
    _db: null as any,
    _client: null as any,
    get db() {
      if (!this._db)
        throw new Error('PGLite context.db accessed before it is initialized');
      return this._db;
    },
    get client() {
      if (!this._client)
        throw new Error(
          'PGLite context.client accessed before it is initialized',
        );
      return this._client;
    },
  };

  // Suites that skip seeds need fresh DBs per-test since they insert
  // their own reference data (uom_dictionary, tax_categories, etc.)
  if (opts?.skipSeeds) {
    let suiteSnapshot: any;

    beforeAll(async () => {
      const memory = await createMemoryDb(opts);
      suiteSnapshot = await memory.client.dumpDataDir();
      await memory.client.close();
    });

    beforeEach(async () => {
      const client = new PGlite({ loadDataDir: suiteSnapshot });
      await client.waitReady;
      const db = drizzle(client, { schema });
      context._db = db;
      context._client = client;
    });

    afterEach(async () => {
      if (context._client) {
        await context._client.close();
      }
      context._db = null;
      context._client = null;
    });

    return context as unknown as PgliteTestContext;
  }

  // Standard path: boot once, truncate transactional tables between tests
  beforeAll(async () => {
    const snapshotPath = path.join(process.cwd(), '.pglite-snapshot.bin');
    if (!fs.existsSync(snapshotPath)) {
      throw new Error(
        'PGlite snapshot not found. Did you forget to run generate-snapshot.ts?',
      );
    }
    const buffer = fs.readFileSync(snapshotPath);
    const snapshot = new File([buffer], 'snapshot.tar');
    const client = new PGlite({ loadDataDir: snapshot });
    await client.waitReady;
    const db = drizzle(client, { schema });
    context._db = db;
    context._client = client;
  });

  afterEach(async () => {
    // Truncate transactional tables to restore seed-only state.
    // Using CASCADE handles any FK dependencies we may have missed.
    try {
      await context._client.exec(
        `TRUNCATE ${TRANSACTIONAL_TABLES.join(', ')} CASCADE`,
      );
    } catch (e: unknown) {
      // Fallback: truncate tables one-by-one if the batch fails
      for (const table of TRANSACTIONAL_TABLES) {
        try {
          await context._client.exec(`TRUNCATE ${table} CASCADE`);
        } catch {
          // Table may not exist — skip
        }
      }
    }

    // Drop any test-created constraints (atomicity tests add CHECK
    // constraints like 'fail_audit', 'fail_on_test' that would
    // persist across tests in the shared PGlite instance).
    for (const [table, constraint] of [
      ['modbm_core.order_events', 'fail_audit'],
      ['modbm_core.account_events', 'fail_on_test'],
    ]) {
      try {
        await context._client.exec(
          `ALTER TABLE ${table} DROP CONSTRAINT IF EXISTS ${constraint}`,
        );
      } catch {
        // Constraint doesn't exist — safe to ignore
      }
    }
  });

  afterAll(async () => {
    if (context._client) {
      await context._client.close();
    }
    context._db = null;
    context._client = null;
  });

  return context as unknown as PgliteTestContext;
}

