  salesOrders,
  salesOrderLineItems,
  taxCategories,
  binContents,
  products,
} from '../src/drizzle/modbm-core-schema';
import { SALES_ORDER_STATE } from '@modbm/shared';
// eslint-disable-next-line @typescript-eslint/no-require-imports
const request = require('supertest');

describe('API E2E — Data Pipeline Verification', () => {
  let app: INestApplication;
  let authToken: string;

  beforeAll(async () => {
    // Clear Prometheus metrics (may be polluted from other tests)
    register.clear();

    const moduleFixture: TestingModule = await (
      await createE2eModule()
    ).compile();

    app = moduleFixture.createNestApplication();
    app.setGlobalPrefix('api');
    app.useGlobalPipes(
      new ValidationPipe({
        whitelist: true,
        transform: true,
      }),
    );
    await app.init();

    // Obtain auth token
    const loginRes = await request(app.getHttpServer())
      .post('/api/auth/login')
      .send({ username: 'admin', password: process.env.ADMIN_PASSWORD })
      .expect(201);

    if (loginRes.status !== 201) {
      throw new Error(
        `${'loginRes'} login failed: ${loginRes.status} ${JSON.stringify(loginRes.body)}`,
