    it('verifies that the system custom line magic product exists', async () => {
      const db = app.get<DrizzleDB>(DRIZZLE);
      const magicProductsRaw = await db.execute(
        sql`SELECT * FROM modbm_core.products WHERE product_number = 'SYSTEM-CUSTOM-LINE'`,
      );
      const magicProducts = Array.isArray(magicProductsRaw)
        ? magicProductsRaw
        : (magicProductsRaw as any).rows || [];

      expect(magicProducts.length).toBe(1);
      expect(magicProducts[0].product_number).toBe('SYSTEM-CUSTOM-LINE');
    });
  });
});

/**
 * E2E Tests — Archive / Unarchive Functionality
 *
 * These tests verify the full archive round-trip across entities:
 *   1. Archive an entity → confirm it disappears from the default list
 *   2. Fetch with ?includeArchived=true → confirm it reappears
 *   3. Unarchive → confirm restored to expected state
 *   4. PO-specific: verify unarchive defaults to 'cancelled'
 *
 * Run with: npm run test:e2e -- --testPathPatterns archive
 * Requires: Docker/Podman stack running with Postgres + populated marts.
 */
import { TestingModule } from '@nestjs/testing';
import { createE2eModule } from './utils/e2e-module';
import { INestApplication } from '@nestjs/common';
import { register } from 'prom-client';
import { AppModule } from '../src/app.module';
import {
  CUSTOMER_STATE,
  PRODUCT_STATE,
  SUPPLIER_STATE,
  SALES_ORDER_STATE,
  PURCHASE_ORDER_STATE,
} from '@modbm/shared';

// eslint-disable-next-line @typescript-eslint/no-require-imports
const request = require('supertest');

describe('Archive E2E — Full Round-Trip', () => {
  let app: INestApplication;
  let adminToken: string;
  let locationId: string;
  let viewerToken: string;

  // IDs captured during setup
  let validCustomerId: string;
  let validProductId: string;
  let validVendorId: string;
  let validLocationId: string;

  beforeAll(async () => {
    register.clear();

    const moduleFixture: TestingModule = await (
      await createE2eModule()
    ).compile();

    app = moduleFixture.createNestApplication();
    app.setGlobalPrefix('api');
    await app.init();

    // Login as admin (has archive action)
    const adminLogin = await request(app.getHttpServer())
      .post('/api/auth/login')
      .send({
        username: 'admin',
        password: process.env.ADMIN_PASSWORD || 'password',
      })
      .expect(201);
    adminToken = adminLogin.body.access_token;
    const locRes = await request(app.getHttpServer())
      .get('/api/inventory/locations')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);
    locationId = locRes.body[0].locationId;

    // Login as viewer (read-only, no archive action)
    const viewerLogin = await request(app.getHttpServer())
      .post('/api/auth/login')
      .send({
        username: 'viewer',
        password: process.env.DEV_VIEWER_PASSWORD || 'password',
      })
      .expect(201);
    viewerToken = viewerLogin.body.access_token;

    // Fetch real IDs from mart data
    const customers = await request(app.getHttpServer())
      .get('/api/customers?limit=1')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);
    validCustomerId = customers.body.data[0].customerId;

    const products = await request(app.getHttpServer())
      .get('/api/products?limit=1')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);
    validProductId = products.body.data[0].productId;

    const suppliers = await request(app.getHttpServer())
      .get('/api/suppliers?limit=1')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);
    validVendorId = suppliers.body.data[0].vendorId;

    const locations = await request(app.getHttpServer())
      .get('/api/inventory/locations')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);
    validLocationId = locations.body[0].locationId;

    // Ensure a default tax category exists (required by SO/PO creation)
    const taxRes = await request(app.getHttpServer())
      .get('/api/tax-categories')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);
    const hasDefault = taxRes.body.some((t: any) => t.isDefault === true);
    if (!hasDefault) {
      await request(app.getHttpServer())
        .post('/api/tax-categories')
        .set('Authorization', `Bearer ${adminToken}`)
