  // ===========================================================================
  // Sales Orders — archive round-trip (must be in terminal state)
  // ===========================================================================

  describe('Sales Orders — archive round-trip', () => {
    let orderId: string;

    it('create and cancel a sales order (terminal state)', async () => {
      // Create draft
      const createRes = await request(app.getHttpServer())
