import { TestingModule } from '@nestjs/testing';
import { createE2eModule } from './utils/e2e-module';
import { INestApplication } from '@nestjs/common';
import { register } from 'prom-client';

// eslint-disable-next-line @typescript-eslint/no-require-imports
const request = require('supertest');

describe('E2E — Backorder Receipt Synchronization (ADV-085)', () => {
  let app: INestApplication;
  let adminToken: string;

  let validVendorId: string;
  let productId: string;
  let locationId: string;
  let customerId: string;

  beforeAll(async () => {
    const moduleFixture: TestingModule = await (
      await createE2eModule()
    ).compile();

    app = moduleFixture.createNestApplication();
    app.setGlobalPrefix('api');
    await app.init();

    // Login as admin
    const adminLogin = await request(app.getHttpServer())
      .post('/api/auth/login')
      .send({
        username: 'admin',
        password: process.env.ADMIN_PASSWORD || 'password',
      });

    expect(adminLogin.status).toBe(201);
    adminToken = adminLogin.body.access_token;

    // Use seeded setup data
    locationId = '10000000-0000-0000-0000-000000000001'; // MAIN
    customerId = '20000000-0000-0000-0000-000000000001'; // E2E Default Customer
    validVendorId = '20000000-0000-0000-0000-000000000002'; // Standard seed vendor

    console.log('Ensuring Location exists...');
    const createLocRes = await request(app.getHttpServer())
      .post('/api/inventory/locations')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        code: `MAIN-${Date.now()}`,
        name: 'Main Warehouse',
        type: 'warehouse',
      });
    console.log('Location Creation Status:', createLocRes.status);
    console.log('Location Creation Body:', JSON.stringify(createLocRes.body));
    locationId = createLocRes.body.locationId || locationId;
    console.log('Final locationId:', locationId);

    const createCustRes = await request(app.getHttpServer())
      .post('/api/customers')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        address1Country: 'AU',
        customerNumber: `CUST-ADV085-${Date.now()}`,
        name: 'ADV-085 Test Customer',
        currencyCode: 'AUD',
      });
    customerId = createCustRes.body.customerId || customerId;
    console.log('Final customerId:', customerId);

    const createVendorRes = await request(app.getHttpServer())
      .post('/api/suppliers')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        address1Country: 'AU',
        vendorNumber: `VEND-ADV085-${Date.now()}`,
        name: 'ADV-085 Test Vendor',
        currencyCode: 'AUD',
      });
    validVendorId = createVendorRes.body.vendorId || validVendorId;
    console.log('Final vendorId:', validVendorId);

    console.log('Fetching Product...');
    // Create a fresh product (0 on hand)
    const productRes = await request(app.getHttpServer())
      .post('/api/products')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        productNumber: `ADV085-P-${Date.now()}`,
        name: 'ADV-085 Backorder Receipt Test Product',
      });

    expect(productRes.status).toBe(201);
    productId = productRes.body.productId;

    // Assign supplier
    const suppRes = await request(app.getHttpServer())
      .post(`/api/products/${productId}/suppliers`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        vendorId: validVendorId,
        isPreferred: true,
        costPrice: '10.00',
        minOrderQty: 1,
      });
    console.log('Supplier Assignment Status:', suppRes.status);
    expect(suppRes.status).toBe(201);
  }, 120_000);

  afterAll(async () => {
    await app.close();
  });

  it('should transition backorder state from awaiting_receipt to received_reserved on Goods Receipt', async () => {
    const server = app.getHttpServer();

    // 1. Create a Sales Order that will trigger a backorder
    const soRes = await request(server)
      .post('/api/sales-orders')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        fulfillmentLocationId: locationId,
        customerId: customerId,
        orderNumber: `SO-ADV085-${Date.now()}`,
        lines: [],
      });
    expect(soRes.status).toBe(201);

    const salesOrderId = soRes.body.salesOrderId;

    // Add line with shortage
    const solRes = await request(server)
      .post(`/api/sales-orders/${salesOrderId}/lines`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        productId,
        quantity: 10,
        pricePerUnit: '100.00',
      });
    expect(solRes.status).toBe(201);

    // Transition to confirmed with backorders
    await request(server)
      .patch(`/api/sales-orders/${salesOrderId}/state`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        stateCode: 'quoted',
      })
      .expect(200);

    await request(server)
      .patch(`/api/sales-orders/${salesOrderId}/state`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        stateCode: 'confirmed',
        generateBackorders: true,
      })
      .expect(200);

    // 2. Verify backorder created in pending_supply
    const openDemandsRes = await request(server)
      .get('/api/allocations/open')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);

    const backorder = openDemandsRes.body.find(
      (d: any) => d.salesOrderId === salesOrderId && d.productId === productId,
    );
    expect(backorder).toBeDefined();
    const backorderId = backorder.id;

    // 3. Create a PO to fulfill the backorder
    const poRes = await request(server)
      .post('/api/purchase-orders')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        orderNumber: `PO-ADV085-${Date.now()}`,
        vendorId: validVendorId,
        deliveryLocationId: locationId,
        currencyCode: 'EUR',
        lines: [
          {
            productId,
            quantity: 10,
            pricePerUnit: '10.00',
          },
        ],
      })
      .expect(201);

    const poId = poRes.body.purchaseOrderId;
    const poLineId = poRes.body.lines[0].purchaseOrderLineId;

    // 4. Link backorder to PO line
    await request(server)
      .post('/api/allocations/link-po')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        demandId: backorderId,
        purchaseOrderLineId: poLineId,
        quantity: 10,
      })
      .expect(201);

    // PO must be ordered to receive goods
    await request(server)
      .patch(`/api/purchase-orders/${poId}/state`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({ stateCode: 'ordered' })
      .expect(200);

    // 5. Create Goods Receipt
    await request(server)
      .post('/api/goods-received')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        vendorId: validVendorId,
        locationId: locationId,
        packingSlipNumber: 'PS-ADV085',
        lines: [
          {
            productId,
            quantityReceived: 10,
          },
        ],
      })
      .expect(201);

    // 6. ASSERTION: Backorder should now be in received_reserved state
    const finalAllocRes = await request(server)
      .get(`/api/allocations/by-po/${poId}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);

    const finalBackorder = finalAllocRes.body.find(
      (d: any) => d.id === backorderId,
    );

    expect(finalBackorder).toBeDefined();
    expect(finalBackorder.stateCode).toBe('received_reserved');
  });

  it('should split backorder record if Goods Receipt is partial', async () => {
    const server = app.getHttpServer();

    // 1. Setup new product and backorder for partial test
    const partialProductRes = await request(server)
      .post('/api/products')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        productNumber: `ADV085-PARTIAL-${Date.now()}`,
        name: 'ADV-085 Partial Receipt Test Product',
      })
      .expect(201);
    const pProductId = partialProductRes.body.productId;

    await request(server)
      .post(`/api/products/${pProductId}/suppliers`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        vendorId: validVendorId,
        isPreferred: true,
        costPrice: '10.00',
        minOrderQty: 1,
      })
      .expect(201);

    const soRes = await request(server)
      .post('/api/sales-orders')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        fulfillmentLocationId: locationId,
        customerId: customerId,
        orderNumber: `SO-ADV085-P-${Date.now()}`,
        lines: [
          { productId: pProductId, quantity: 10, pricePerUnit: '100.00' },
        ],
      });
    expect(soRes.status).toBe(201);

    const salesOrderId = soRes.body.salesOrderId;

    await request(server)
      .patch(`/api/sales-orders/${salesOrderId}/state`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({ stateCode: 'quoted' })
      .expect(200);

    await request(server)
      .patch(`/api/sales-orders/${salesOrderId}/state`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({ stateCode: 'confirmed', generateBackorders: true })
      .expect(200);

    const openDemandsRes = await request(server)
      .get('/api/allocations/open')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);

    const backorder = openDemandsRes.body.find(
      (d: any) => d.productId === pProductId,
    );
    const backorderId = backorder.id;

    const poRes = await request(server)
      .post('/api/purchase-orders')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        orderNumber: `PO-ADV085-P-${Date.now()}`,
        vendorId: validVendorId,
        deliveryLocationId: locationId,
        currencyCode: 'EUR',
        lines: [{ productId: pProductId, quantity: 10, pricePerUnit: '10.00' }],
      })
      .expect(201);

    const poId = poRes.body.purchaseOrderId;
    const poLineId = poRes.body.lines[0].purchaseOrderLineId;

    await request(server)
      .post('/api/allocations/link-po')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        demandId: backorderId,
        purchaseOrderLineId: poLineId,
        quantity: 10,
      })
      .expect(201);

    await request(server)
      .patch(`/api/purchase-orders/${poId}/state`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({ stateCode: 'ordered' })
      .expect(200);

    // 2. Receive PARTIAL (4 units out of 10)
    await request(server)
      .post('/api/goods-received')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        vendorId: validVendorId,
        locationId: locationId,
        packingSlipNumber: 'PS-ADV085-PARTIAL',
        lines: [{ productId: pProductId, quantityReceived: 4 }],
      })
      .expect(201);

    // 3. ASSERTION: Should have two backorder records now
    const finalAllocRes = await request(server)
      .get(`/api/allocations/by-po/${poId}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);

    const receivedPart = finalAllocRes.body.find(
      (d: any) => d.stateCode === 'received_reserved',
    );
    const awaitingPart = finalAllocRes.body.find(
      (d: any) => d.stateCode === 'awaiting_receipt',
    );

    expect(receivedPart).toBeDefined();
    expect(receivedPart.quantity).toBe(4);

    expect(awaitingPart).toBeDefined();
    expect(awaitingPart.quantity).toBe(6);
  });
});

import { TestingModule } from '@nestjs/testing';
import { createE2eModule } from './utils/e2e-module';
import { INestApplication } from '@nestjs/common';
import './suite-setup';
import request from 'supertest';
import { DRIZZLE } from '../src/drizzle/drizzle.module';
import {
  glAccounts,
  reconciliationRules,
  csvMappingProfiles,
} from '../src/drizzle/modbm-core-schema';

describe('BankFeedsController (e2e)', () => {
  let app: INestApplication;
  let adminToken: string;
  let bankAccountId: string;

  beforeAll(async () => {
    const moduleFixture: TestingModule = await (
      await createE2eModule()
    ).compile();

    app = moduleFixture.createNestApplication();
    app.setGlobalPrefix('api');
    await app.init();

    // Login
    const adminRes = await request(app.getHttpServer())
      .post('/api/auth/login')
      .send({
        username: 'admin',
        password: process.env.ADMIN_PASSWORD || 'password',
      });

    adminToken = adminRes.body.access_token;

    // Insert bank account directly to avoid any group account issues
    const db = app.get(DRIZZLE);

    const inserted = await db
      .insert(glAccounts)
      .values({
        accountCode: '9999-BANK',
        name: 'E2E Bank Account',
        accountType: 'asset',
        currencyCode: 'AUD',
        isBankAccount: true,
        isGroup: false,
      })
      .onConflictDoUpdate({
        target: glAccounts.accountCode,
        set: { name: 'E2E Bank Account' },
      })
      .returning();

    bankAccountId = inserted[0].glAccountId;

    // Clean up any previously created rules or profiles from failed tests
    await db.delete(reconciliationRules);
    await db.delete(csvMappingProfiles);
  });

  afterAll(async () => {
    await app.close();
  });

  it('should parse CSV headers correctly', async () => {
    const csvBuffer = Buffer.from(
      'Date,Amount,Description\n2023-01-01,100,Test',
    );
    const res = await request(app.getHttpServer())
      .post('/api/gl/bank-feeds/parse')
      .set('Authorization', `Bearer ${adminToken}`)
      .attach('file', csvBuffer, 'test.csv')
      .expect(201);

    expect(res.body.headers).toBeDefined();
    expect(res.body.headers).toEqual(
      expect.arrayContaining(['Date', 'Amount', 'Description']),
    );
    expect(res.body.sampleRows).toHaveLength(1);
  });

  let profileId: string;
  it('should create a mapping profile', async () => {
    const res = await request(app.getHttpServer())
      .post('/api/gl/bank-feeds/profiles')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        glAccountId: bankAccountId,
        name: 'Test Profile',
        dateColumn: '0',
        amountColumn: '1',
        descriptionColumn: '2',
        headerRows: 1,
      })
      .expect(201);

    expect(res.body.profileId).toBeDefined();
    profileId = res.body.profileId;
  });

  it('should get mapping profiles', async () => {
    const res = await request(app.getHttpServer())
      .get(`/api/gl/bank-feeds/profiles/${bankAccountId}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);

    expect(Array.isArray(res.body)).toBe(true);
    expect(res.body.find((p: any) => p.profileId === profileId)).toBeDefined();
  });

  it('should update a mapping profile', async () => {
    const res = await request(app.getHttpServer())
      .put(`/api/gl/bank-feeds/profiles/${profileId}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        name: 'Updated Profile Name',
      })
      .expect(200);

    expect(res.body.name).toBe('Updated Profile Name');
  });

  it('should delete a mapping profile', async () => {
    // Create a temporary profile to delete
    const tempProfileRes = await request(app.getHttpServer())
      .post('/api/gl/bank-feeds/profiles')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        glAccountId: bankAccountId,
        name: 'Temp Profile for Deletion',
        dateColumn: '0',
        amountColumn: '1',
        descriptionColumn: '2',
        headerRows: 1,
      })
      .expect(201);

    const tempProfileId = tempProfileRes.body.profileId;

    await request(app.getHttpServer())
      .delete(`/api/gl/bank-feeds/profiles/${tempProfileId}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);

    const res = await request(app.getHttpServer())
      .get(`/api/gl/bank-feeds/profiles/${bankAccountId}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);

    expect(
      res.body.find((p: any) => p.profileId === tempProfileId),
    ).toBeUndefined();
  });

  let targetAccountId: string;
  it('should create a reconciliation rule', async () => {
    const db = app.get(DRIZZLE);
    const targetInserted = await db
      .insert(glAccounts)
      .values({
        accountCode: '8888-TARGET',
        name: 'E2E Target Account',
        accountType: 'expense',
        currencyCode: 'AUD',
        isGroup: false,
        isBankAccount: false,
      })
      .onConflictDoUpdate({
        target: glAccounts.accountCode,
        set: { name: 'E2E Target Account' },
      })
      .returning();

    targetAccountId = targetInserted[0].glAccountId;

    const res = await request(app.getHttpServer())
      .post('/api/gl/bank-feeds/rules')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        conditionType: 'contains',
        conditionValue: 'STRIPE PAYOUT',
        targetGlAccountId: targetAccountId,
      })
      .expect(201);

    expect(res.body.ruleId).toBeDefined();
  });

  it('should import CSV and auto-match rules', async () => {
    const csvBuffer = Buffer.from(
      'Date,Amount,Description\n2026-05-25,150.00,STRIPE PAYOUT\n2026-05-26,-50.00,UNKNOWN FEE',
    );

    const res = await request(app.getHttpServer())
      .post('/api/gl/bank-feeds/import')
      .set('Authorization', `Bearer ${adminToken}`)
      .field('glAccountId', bankAccountId)
      .field('profileId', profileId)
      .attach('file', csvBuffer, 'statement.csv');

    if (res.status !== 201) console.error('Import Error:', res.body);
    expect(res.status).toBe(201);

    expect(res.body.autoMatchedCount).toBe(1);
