const request = require('supertest');

describe('Account Groups (e2e)', () => {
  let app: INestApplication;
  let adminToken: string;

  beforeAll(async () => {
    const moduleFixture: TestingModule = await (
      await createE2eModule()
    ).compile();

    app = moduleFixture.createNestApplication();
    app.setGlobalPrefix('api');
    await app.init();

    // Login as admin
    const adminRes = await request(app.getHttpServer())
      .post('/api/auth/login')
      .send({
        username: 'admin',
        password: process.env.ADMIN_PASSWORD || 'password',
      });
    if (adminRes.status !== 201) {
      throw new Error(
        `${'adminRes'} login failed: ${adminRes.status} ${JSON.stringify(adminRes.body)}`,
      );
    }
    adminToken = adminRes.body.access_token;
  });

  afterAll(async () => {
    await app.close();
  });

  it('CRUD /api/account-groups — full lifecycle', async () => {
    const groupCode = `ACC-GRP-${Date.now()}`;

    // 1. Create a group
    const createRes = await request(app.getHttpServer())
      .post('/api/customer-groups')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        groupCode,
        name: 'E2E Test Account Group',
      });
    expect(createRes.status).toBe(201);
    expect(createRes.body.customerGroupId).toBeDefined();
    expect(createRes.body.groupCode).toBe(groupCode);
    const groupId = createRes.body.customerGroupId;

    // 2. Read all groups
    const listRes = await request(app.getHttpServer())
      .get('/api/customer-groups')
      .set('Authorization', `Bearer ${adminToken}`);
    expect(listRes.status).toBe(200);
    expect(Array.isArray(listRes.body)).toBe(true);
    expect(
      listRes.body.find((g: any) => g.customerGroupId === groupId),
    ).toBeDefined();

    // 3. Read single group
    const getRes = await request(app.getHttpServer())
      .get(`/api/customer-groups/${groupId}`)
      .set('Authorization', `Bearer ${adminToken}`);
    expect(getRes.status).toBe(200);
    expect(getRes.body.name).toBe('E2E Test Account Group');

    // 4. Assign an account to the group
    const createCustomerRes = await request(app.getHttpServer())
      .post('/api/customers')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        address1Country: 'AU',
        customerNumber: `GRP-MEMBER-${Date.now()}`,
        name: 'Group Member',
        customerGroupId: groupId,
      });
    expect(createCustomerRes.status).toBe(201);
    expect(createCustomerRes.body.customerGroupId).toBe(groupId);

    // 5. Verify the group name merges into the account payload correctly
    const accountListRes = await request(app.getHttpServer())
      .get('/api/customers?limit=1000&orderDirection=desc')
      .set('Authorization', `Bearer ${adminToken}`);
    const foundAcc = accountListRes.body.data.find(
      (a: any) => a.customerId === createCustomerRes.body.customerId,
    );
    expect(foundAcc).toBeDefined();
    expect(foundAcc.customerGroupCode).toBe(groupCode);
    expect(foundAcc.customerGroupName).toBe('E2E Test Account Group');

    // 6. Update the group
    const updateRes = await request(app.getHttpServer())
      .patch(`/api/customer-groups/${groupId}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        name: 'Updated Account Group',
      });
    expect(updateRes.status).toBe(200);
    expect(updateRes.body.name).toBe('Updated Account Group');

    // 7. Delete the group (first cleanly un-assign the account to avoid FK errors)
    await request(app.getHttpServer())
      .patch(`/api/customers/${createCustomerRes.body.customerId}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({ customerGroupId: null });

    const deleteRes = await request(app.getHttpServer())
      .delete(`/api/customer-groups/${groupId}`)
      .set('Authorization', `Bearer ${adminToken}`);
    expect(deleteRes.status).toBe(200);
    expect(deleteRes.body.deleted).toBe(true);
  });
});

import { TestingModule } from '@nestjs/testing';
import { createE2eModule } from './utils/e2e-module';
import { INestApplication } from '@nestjs/common';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import * as schema from '../src/drizzle/modbm-core-schema';

describe('DTO-Schema Reflection Parity (e2e)', () => {
  let app: INestApplication;
  let document: any;

  beforeAll(async () => {
    const moduleFixture: TestingModule = await (
      await createE2eModule()
    ).compile();

    app = moduleFixture.createNestApplication();
    await app.init();

    const config = new DocumentBuilder()
      .setTitle('HeroBM API')
      .setVersion('1.0')
      .build();
    document = SwaggerModule.createDocument(app, config);
  });

  afterAll(async () => {
    await app.close();
  });

  const MANUAL_MAPPING: Record<string, string> = {
    PurchaseOrderLineResponseDto: 'purchaseOrderLineItems',
    CreatePurchaseOrderLineDto: 'purchaseOrderLineItems',
    UpdatePurchaseOrderLineDto: 'purchaseOrderLineItems',
    SalesOrderLineResponseDto: 'salesOrderLineItems',
    CreateSalesOrderLineDto: 'salesOrderLineItems',
    UpdateSalesOrderLineDto: 'salesOrderLineItems',
    GoodsReceivedLineDto: 'goodsReceivedLines',
    GoodsReceivedLineResponseDto: 'goodsReceivedLines',
  };

  function guessTableName(dtoName: string): string | null {
    if (MANUAL_MAPPING[dtoName]) return MANUAL_MAPPING[dtoName];

    let base = dtoName
      .replace(/ResponseDto$/, '')
      .replace(/Dto$/, '')
      .replace(/^Create/, '')
      .replace(/^Update/, '')
      .replace(/^Partial/, '');

    if (!base) return null;

    // lowerCamelCase
    base = base.charAt(0).toLowerCase() + base.slice(1);

    // pluralize
    let table = base.endsWith('s') ? base : base + 's';
    if ((schema as any)[table]) return table;

    // try 'es'
    table = base + 'es';
    if ((schema as any)[table]) return table;

    // try 'ies'
    if (base.endsWith('y')) {
      table = base.slice(0, -1) + 'ies';
      if ((schema as any)[table]) return table;
    }

    return null;
  }

  it('should not contain fake fields in strictly typed DTOs', () => {
    const schemas = document.components?.schemas || {};
    const errors: string[] = [];
    let checkedCount = 0;
    let checkedDtos = 0;

    for (const [dtoName, dtoSchema] of Object.entries<any>(schemas)) {
      if (!dtoName.endsWith('Dto')) continue;

      const tableName = guessTableName(dtoName);
      if (!tableName) continue;

      const tableDef = (schema as any)[tableName];
      if (!tableDef || !tableDef._ || !tableDef._.columns) continue;

      checkedDtos++;
      const columns = tableDef._.columns;
      const properties = dtoSchema.properties || {};

      for (const [propName, propDef] of Object.entries<any>(properties)) {
        // Skip relations (arrays or objects)
        if (
          propDef.type === 'array' ||
          propDef.type === 'object' ||
          propDef.$ref
        ) {
          continue;
        }

        checkedCount++;

        // Check if property exists in DB columns
        let exists = false;

        // Drizzle columns might be snake_case in db, but camelCase in the schema object keys
        if (columns[propName]) {
          exists = true;
        } else {
          // fallback check if any column has the exact same name
          for (const col of Object.values<any>(columns)) {
            if (col.name === propName || col.key === propName) {
              exists = true;
              break;
            }
          }
        }

        if (!exists) {
          const isComputed = propDef.description?.includes('[COMPUTED]');
          if (!isComputed) {
            errors.push(
              `DTO '${dtoName}' exposes field '${propName}' which does not exist in table '${tableName}'. If this is intentional, decorate it with @ComputedMetric().`,
            );
          }
        }
      }
    }

    if (errors.length > 0) {
      throw new Error(
        `\nFake fields detected in DTOs:\n\n${errors.join('\n')}\n`,
      );
    }
    console.log(
      `Successfully verified ${checkedCount} fields across ${checkedDtos} mapped DTOs.`,
    );
  });
});

import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication } from '@nestjs/common';
// eslint-disable-next-line @typescript-eslint/no-require-imports
const request = require('supertest');
import { AppModule } from '../src/app.module';
import { DrizzleDB, DRIZZLE } from '../src/drizzle/drizzle.module';
import { apiKeys, webhooks, outbox } from '../src/drizzle/modbm-core-schema';
import * as bcrypt from 'bcrypt';
import { eq } from 'drizzle-orm';
import { processEvent } from '../../worker/src/relay.service';
import express from 'express';
import { WebhookReceiver } from '../../../packages/sdk/src/server/WebhookReceiver';

describe('Events (e2e)', () => {
  let app: INestApplication;
  let db: DrizzleDB;
  let server: any;
  const rawKey = 'super-secret-events-key-' + Date.now();
  let webhookSecret: string;
  let expressApp: any;
  let expressServer: any;
  let receivedPayload: any = null;

  beforeAll(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleFixture.createNestApplication();
    app.setGlobalPrefix('api');
    await app.init();
    db = app.get<DrizzleDB>(DRIZZLE);
    server = app.getHttpServer();

    const keyHash = await bcrypt.hash(rawKey, 10);
    await db.insert(apiKeys).values({
      name: 'Events Test Key',
      keyHash,
      prefix: rawKey.substring(0, 4),
      role: 'admin',
      isActive: true,
      createdBy: 'test',
    });

    // Create a webhook subscription for testing
    const res = await request(server)
      .post('/api/webhooks')
      .set('x-api-key', rawKey)
      .send({
        targetUrl: 'http://127.0.0.1:4005/webhook', // Dummy test server
        eventTypes: ['test.event'],
      });

    webhookSecret = res.body.secretKey;

    // Start a mock Express server to receive the webhook using the new SDK
    expressApp = express();
    const receiver = new WebhookReceiver({ secret: webhookSecret });

    receiver.on('test.event', (payload) => {
      receivedPayload = payload;
    });

    expressApp.post(
      '/webhook',
      express.raw({ type: 'application/json' }),
      receiver.expressMiddleware(),
    );
    expressServer = expressApp.listen(4005);
  });

  afterAll(async () => {
    expressServer?.close();
    await db.delete(webhooks);
    await db.delete(outbox);
    await db.delete(apiKeys).where(eq(apiKeys.prefix, rawKey.substring(0, 4)));
    await app.close();
  });

  it('should publish an event and dispatch it to WebhookReceiver', async () => {
    // 1. Publish Event via API
    const res = await request(server)
      .post('/api/events/publish')
      .set('x-api-key', rawKey)
      .send({
        type: 'test.event',
        payload: { message: 'hello world' },
      })
      .expect(201);

    expect(res.body.success).toBe(true);
    expect(res.body.outboxId).toBeDefined();

    // 2. Read from Outbox
    const events = await db
      .select()
      .from(outbox)
      .where(eq(outbox.outboxId, res.body.outboxId));
    expect(events.length).toBe(1);

    const mockJob = {
      data: {
        eventId: events[0].outboxId,
        type: events[0].eventType,
        entityId: events[0].entityId,
        entityType: events[0].entityType,
        createdOn: events[0].createdOn,
        payload: events[0].payload,
      },
    };

    await processEvent(mockJob as any, db);

    // Give the async fetch inside processEvent a tiny moment to complete and hit our Express server
    await new Promise((resolve) => setTimeout(resolve, 500));

    // 4. Verify WebhookReceiver successfully handled it
    expect(receivedPayload).toBeDefined();
    expect(receivedPayload.payload.message).toBe('hello world');
  });
});

