        .send({
          fulfillmentLocationId: locationId,

          customerId: validCustomerId,
          lines: [],
        })
        .expect(401);
    });
  });

  // =========================================================================
  // Full order lifecycle
  // =========================================================================

  describe('Full order lifecycle', () => {
    let orderId: string;
    let orderNumber: string;
    let firstLineId: string;
    let addedLineId: string;

    it('POST /api/sales-orders — creates a new order in draft state', async () => {
      const res = await request(app.getHttpServer())
        .post('/api/sales-orders')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          fulfillmentLocationId: locationId,

          customerId: validCustomerId,
          name: 'E2E-OW Test Order',
          notes: 'Created by E2E test suite',
          lines: [
            {
              productId: validProductId,
              productDescription: 'Test Product A',
              quantity: '10',
              pricePerUnit: '25.50',
              discountPercentage: '5',
              tax: '12.13',
            },
            {
              productId: secondProductId,
              productDescription: 'Test Product B',
              quantity: '3',
              pricePerUnit: '100.00',
            },
          ],
        })
        .expect(201);

      expect(res.body).toHaveProperty('salesOrderId');
      expect(res.body).toHaveProperty('orderNumber');
      expect(res.body.stateCode).toBe(SALES_ORDER_STATE.DRAFT);
      expect(res.body.name).toBe('E2E-OW Test Order');

      orderId = res.body.salesOrderId;
      orderNumber = res.body.orderNumber;
    });

    it('GET /api/sales-orders/:id — retrieves the order with lines and events', async () => {
      const res = await request(app.getHttpServer())
        .get(`/api/sales-orders/${orderId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      expect(res.body.salesOrderId).toBe(orderId);
      expect(res.body.orderNumber).toBe(orderNumber);
      expect(res.body.lines).toHaveLength(2);
      expect(res.body.events).toHaveLength(1);
      expect(res.body.events[0].eventType).toBe('created');

      // Verify line amount was computed correctly
      const lineA = res.body.lines.find(
        (l: any) => l.productDescription === 'Test Product A',
      );
      expect(lineA).toBeDefined();
      // 10 × 25.50 × (1 − 0.05) = 242.25
      expect(parseFloat(lineA.amount)).toBeCloseTo(242.25, 2);
      const expectedTotal = 242.25 + parseFloat(lineA.tax || '0');
      expect(parseFloat(lineA.totalAmount)).toBeCloseTo(expectedTotal, 2);

      firstLineId = res.body.lines[0].salesOrderLineId;
    });

    // NOTE: Legacy PDF report routes (sales-quote-report, sales-invoice-report)
    // were removed during the Typst migration. PDF generation is now handled
    // by the dynamic reports engine: POST /api/reports/hooks/:hookSlug/run

    it('PATCH /api/sales-orders/:id — updates order header', async () => {
      const res = await request(app.getHttpServer())
        .patch(`/api/sales-orders/${orderId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          name: 'E2E-OW Test Order — Updated',
          customerOrderNumber: 'CUST-PO-12345',
        })
        .expect(200);

      expect(res.body.name).toBe('E2E-OW Test Order — Updated');
      expect(res.body.customerOrderNumber).toBe('CUST-PO-12345');
    });

    it('POST /api/sales-orders/:id/lines — adds a third line', async () => {
      const res = await request(app.getHttpServer())
        .post(`/api/sales-orders/${orderId}/lines`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          productId: thirdProductId,
          productDescription: 'Test Product C',
          quantity: '7',
          pricePerUnit: '15.00',
        })
        .expect(201);

      expect(res.body).toHaveProperty('salesOrderLineId');
      expect(res.body.lineNumber).toBe(3);
      addedLineId = res.body.salesOrderLineId;
    });

    it('PATCH /api/sales-orders/:id/lines/:lineId — updates a line', async () => {
      const res = await request(app.getHttpServer())
        .patch(`/api/sales-orders/${orderId}/lines/${addedLineId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ quantity: '14', pricePerUnit: '15.00' })
        .expect(200);

      // 14 × 15.00 = 210.00
      expect(parseFloat(res.body.amount)).toBeCloseTo(210.0, 2);
    });

    it('DELETE /api/sales-orders/:id/lines/:lineId — removes a line', async () => {
      await request(app.getHttpServer())
        .delete(`/api/sales-orders/${orderId}/lines/${addedLineId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      // Verify line count is back to 2
      const detail = await request(app.getHttpServer())
        .get(`/api/sales-orders/${orderId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);
      expect(detail.body.lines).toHaveLength(2);
    });

    it('PATCH /api/sales-orders/:id/state — transitions through the full lifecycle', async () => {
      const transitions = [
        SALES_ORDER_STATE.QUOTED,
        SALES_ORDER_STATE.CONFIRMED,
        SALES_ORDER_STATE.PICKING,
        SALES_ORDER_STATE.SHIPPED,
        SALES_ORDER_STATE.INVOICED,
      ];

      // Helper: resolve first bin and pick all lines then ship
      async function pickAndShipOrder(oid: string) {
        const binsRes = await request(app.getHttpServer())
          .get('/api/inventory/bins')
          .set('Authorization', `Bearer ${adminToken}`)
          .expect(200);
        // Hardcode a valid storage bin ID from seeds, as /inventory/bins now returns binContents
        const binId =
          binsRes.body.data[0]?.binId || '40000000-0000-0000-0000-000000000003';

        const detail = await request(app.getHttpServer())
          .get(`/api/sales-orders/${oid}`)
          .set('Authorization', `Bearer ${adminToken}`)
          .expect(200);

        const shipLines: any[] = [];
        for (const line of detail.body.lines) {
          await request(app.getHttpServer())
            .post(
              `/api/sales-orders/${oid}/picking/lines/${line.salesOrderLineId}`,
            )
            .set('Authorization', `Bearer ${adminToken}`)
            .send({ binId, quantity: line.quantity })
            .expect(201);
          shipLines.push({
            salesOrderLineId: line.salesOrderLineId,
            quantityShipped: line.quantity,
          });
        }

        const shipRes = await request(app.getHttpServer())
          .post(`/api/sales-orders/${oid}/shipments`)
          .set('Authorization', `Bearer ${adminToken}`)
          .send({ lines: shipLines })
          .expect(201);

        // Dispatched automatically upon creation
      }

      for (const nextState of transitions) {
        if (nextState === SALES_ORDER_STATE.SHIPPED) {
          await pickAndShipOrder(orderId);
          // shipped is handled by auto-transition on dispatch
          continue;
        }

        const res = await request(app.getHttpServer())
          .patch(`/api/sales-orders/${orderId}/state`)
          .set('Authorization', `Bearer ${adminToken}`)
          .send({ stateCode: nextState, generateBackorders: true })
          .expect(200);
        expect(res.body.stateCode).toBe(nextState);
      }
    });

    it('event log captures the full history', async () => {
      const res = await request(app.getHttpServer())
        .get(`/api/sales-orders/${orderId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      const eventTypes = res.body.events.map((e: any) => e.eventType);
      expect(eventTypes).toContain('created');
      expect(eventTypes).toContain('updated');
      expect(eventTypes).toContain('line_added');
      expect(eventTypes).toContain('line_updated');
      expect(eventTypes).toContain('line_removed');
      expect(eventTypes).toContain('status_changed');

      // Should have status_changed + auto_status_changed events covering full lifecycle
      const statusChanges = res.body.events.filter(
        (e: any) =>
          e.eventType === 'status_changed' ||
          e.eventType === 'auto_status_changed',
      );
      expect(statusChanges.length).toBeGreaterThanOrEqual(4);
    });
  });

  // =========================================================================
  // Validation & error handling
  // =========================================================================

  describe('Validation & error handling', () => {
    let draftOrderId: string;

    beforeAll(async () => {
      // Create a fresh draft order for validation tests
      const res = await request(app.getHttpServer())
        .post('/api/sales-orders')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          fulfillmentLocationId: locationId,

          customerId: validCustomerId,
          lines: [
            {
              productId: secondProductId,
              quantity: '1',
              pricePerUnit: '10.00',
            },
          ],
        })
        .expect(201);
      draftOrderId = res.body.salesOrderId;
    });

    it('create with unknown customer returns 400', async () => {
      await request(app.getHttpServer())
        .post('/api/sales-orders')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          fulfillmentLocationId: locationId,

          customerId: 'NONEXISTENT-CUSTOMER-ID',
          lines: [
            {
              productId: validProductId,
              quantity: '1',
              pricePerUnit: '10.00',
            },
          ],
        })
        .expect(400);
    });

    it('create with unknown product returns 400', async () => {
      await request(app.getHttpServer())
        .post('/api/sales-orders')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          fulfillmentLocationId: locationId,

          customerId: validCustomerId,
          lines: [
            {
              productId: 'NONEXISTENT-PRODUCT-ID',
              quantity: '1',
              pricePerUnit: '10.00',
            },
          ],
        })
        .expect(400);
    });

    it('invalid state transition returns 400', async () => {
      const res = await request(app.getHttpServer())
        .patch(`/api/sales-orders/${draftOrderId}/state`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ stateCode: SALES_ORDER_STATE.SHIPPED })
        .expect(400);

      expect(res.body.message).toContain('Cannot transition');
    });

    it('unknown state name returns 400', async () => {
      await request(app.getHttpServer())
        .patch(`/api/sales-orders/${draftOrderId}/state`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ stateCode: 'bogus' })
        .expect(400);
    });

    it('update on invoiced order returns 400', async () => {
      // First move our draft order to invoiced state
      const invoicedOrder = await request(app.getHttpServer())
        .post('/api/sales-orders')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          fulfillmentLocationId: locationId,

          customerId: validCustomerId,
          lines: [
            {
              productId: validProductId,
              quantity: '1',
              pricePerUnit: '10.00',
            },
          ],
        })
        .expect(201);

      const invoicedId = invoicedOrder.body.salesOrderId;

      // Move through lifecycle to invoiced
      for (const state of [
        SALES_ORDER_STATE.QUOTED,
        SALES_ORDER_STATE.CONFIRMED,
        SALES_ORDER_STATE.PICKING,
        SALES_ORDER_STATE.SHIPPED,
        SALES_ORDER_STATE.INVOICED,
      ]) {
        if (state === SALES_ORDER_STATE.SHIPPED) {
          // Pick all lines and create + dispatch shipment
          const binsRes = await request(app.getHttpServer())
            .get('/api/inventory/bins')
            .set('Authorization', `Bearer ${adminToken}`)
            .expect(200);
          const binId =
            binsRes.body.data[0]?.binId ||
            '40000000-0000-0000-0000-000000000003';

          const detail = await request(app.getHttpServer())
            .get(`/api/sales-orders/${invoicedId}`)
            .set('Authorization', `Bearer ${adminToken}`)
            .expect(200);

          const shipLines: any[] = [];
          for (const line of detail.body.lines) {
            await request(app.getHttpServer())
              .post(
                `/api/sales-orders/${invoicedId}/picking/lines/${line.salesOrderLineId}`,
              )
              .set('Authorization', `Bearer ${adminToken}`)
              .send({ binId, quantity: line.quantity })
              .expect(201);
            shipLines.push({
              salesOrderLineId: line.salesOrderLineId,
              quantityShipped: line.quantity,
            });
          }

          const shipRes = await request(app.getHttpServer())
            .post(`/api/sales-orders/${invoicedId}/shipments`)
            .set('Authorization', `Bearer ${adminToken}`)
            .send({ lines: shipLines })
            .expect(201);

          // shipped state is auto-transitioned
          continue;
        }

        await request(app.getHttpServer())
          .patch(`/api/sales-orders/${invoicedId}/state`)
          .set('Authorization', `Bearer ${adminToken}`)
          .send({ stateCode: state, generateBackorders: false })
          .expect(200);
      }

      // Now try to update it
      await request(app.getHttpServer())
        .patch(`/api/sales-orders/${invoicedId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ name: 'Should fail' })
        .expect(400);
    });

    it('add line to cancelled order returns 400', async () => {
      // Create and cancel an order
      const res = await request(app.getHttpServer())
        .post('/api/sales-orders')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          fulfillmentLocationId: locationId,

          customerId: validCustomerId,
          lines: [
            {
              productId: validProductId,
              quantity: '1',
              pricePerUnit: '10.00',
            },
          ],
        })
        .expect(201);

      await request(app.getHttpServer())
        .patch(`/api/sales-orders/${res.body.salesOrderId}/state`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ stateCode: SALES_ORDER_STATE.CANCELLED })
        .expect(200);

      // Try adding a line — should fail
      await request(app.getHttpServer())
        .post(`/api/sales-orders/${res.body.salesOrderId}/lines`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          productId: validProductId,
          quantity: '1',
          pricePerUnit: '10.00',
        })
        .expect(400);
    });

    it('unknown order ID returns 404', async () => {
      await request(app.getHttpServer())
        .get('/api/sales-orders/00000000-0000-0000-0000-000000000000')
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(404);
    });

    it('create with duplicate products returns 400', async () => {
      await request(app.getHttpServer())
        .post('/api/sales-orders')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          fulfillmentLocationId: locationId,

          customerId: validCustomerId,
          lines: [
            {
              productId: secondProductId,
              quantity: '1',
              pricePerUnit: '10.00',
            },
            {
              productId: secondProductId,
              quantity: '2',
              pricePerUnit: '10.00',
            },
          ],
        })
        .expect(400);
    });

    it('add duplicate product as new line returns 400', async () => {
      // Order created in beforeAll already has validProductId
      await request(app.getHttpServer())
        .post(`/api/sales-orders/${draftOrderId}/lines`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          productId: secondProductId,
          quantity: '5',
          pricePerUnit: '10.00',
        })
        .expect(400);
    });
  });

  // =========================================================================
  // App order listing
  // =========================================================================

  describe('App order listing', () => {
    it('GET /api/sales-orders — returns orders', async () => {
      const res = await request(app.getHttpServer())
        .get('/api/sales-orders')
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      expect(res.body).toHaveProperty('data');
      expect(Array.isArray(res.body.data)).toBe(true);
      // We created orders in previous tests, should have at least 1
      expect(res.body.data.length).toBeGreaterThan(0);
      // Verify the listing contains our app-created orders
      const appOrders = res.body.data.filter((o: any) =>
        o.orderNumber?.startsWith('ORD-'),
      );
      expect(appOrders.length).toBeGreaterThan(0);
      expect(appOrders[0]).toHaveProperty('id');
      expect(appOrders[0]).toHaveProperty('orderNumber');
    });
  });
});

import { TestingModule } from '@nestjs/testing';
import { INestApplication } from '@nestjs/common';
// eslint-disable-next-line @typescript-eslint/no-require-imports
const request = require('supertest');
import { createE2eModule } from './utils/e2e-module';

describe('Permissions & RBAC (e2e)', () => {
  let app: INestApplication;
  let adminToken: string;
  let viewerToken: string;
  let salesToken: string;
  let testUserToken: string;

  beforeAll(async () => {
    const moduleFixture: TestingModule = await (
      await createE2eModule()
    ).compile();

    app = moduleFixture.createNestApplication();
    app.setGlobalPrefix('api');
    await app.init();

    // In a real e2e environment, we would use provision-e2e-db.
    // For this demonstration, assume standard users are seeded.
    const getTestTokenDirect = async (username: string, pass: string) => {
      const res = await request(app.getHttpServer())
        .post('/api/auth/login')
        .send({ username, password: pass });
      if (res.status !== 201)
        throw new Error(`Login failed for ${username}: ${res.status}`);
      return res.body.access_token;
    };

    adminToken = await getTestTokenDirect(
      'admin',
      process.env.ADMIN_PASSWORD || 'password',
    );
    viewerToken = await getTestTokenDirect(
      'viewer',
      process.env.DEV_VIEWER_PASSWORD || 'password',
    );
    salesToken = await getTestTokenDirect('sales', 'password');
  });

  afterAll(async () => {
    await app.close();
  });

  it('Viewer should be able to read customers but not write', async () => {
    // Read -> 200
    await request(app.getHttpServer())
      .get('/api/customers')
      .set('Authorization', `Bearer ${viewerToken}`)
      .expect(200);

    // Write -> 403
    await request(app.getHttpServer())
      .post('/api/customers')
      .set('Authorization', `Bearer ${viewerToken}`)
      .send({
        address1Country: 'AU',
        name: 'Test Customer',
      })
      .expect(403);
  });

  it('Admin should be able to write customers', async () => {
    await request(app.getHttpServer())
      .post('/api/customers')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        address1Country: 'AU',
        customerNumber: 'CUST-ADMIN-TEST',
        name: 'Test Customer Admin',
      })
      .expect(201);
  });

  it('Dynamic Permission: Grant write access to a new resource', async () => {
    // Viewer tries to write to webhooks -> 403
    await request(app.getHttpServer())
      .post('/api/webhooks')
      .set('Authorization', `Bearer ${viewerToken}`)
      .send({ targetUrl: 'http://test' })
      .expect(403);

    // Fetch existing viewer permissions
    const getRes = await request(app.getHttpServer())
      .get('/api/roles/viewer')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);
    const existingPermissions = getRes.body.permissions;

    // Admin adds webhooks write to viewer
    await request(app.getHttpServer())
      .post('/api/roles/viewer')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        permissions: [
          ...existingPermissions,
          { resource: 'webhooks', action: 'write', effect: 'allow' },
        ],
      })
      .expect(201);

    // Viewer tries again -> 201 (or 400 if validation fails, but not 403)
    const res = await request(app.getHttpServer())
      .post('/api/webhooks')
      .set('Authorization', `Bearer ${viewerToken}`)
      .send({
        targetUrl: 'http://test',
        eventTypes: [],
        secretKey: 'secret' as string,
      }); // TEST_CREDENTIAL

    expect(res.status).not.toBe(403);
  });

  it('Remove a permission: Revoke webhooks write from viewer', async () => {
    // Fetch existing viewer permissions
    const getRes = await request(app.getHttpServer())
      .get('/api/roles/viewer')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);

    // Remove webhooks write
    const restoredPermissions = getRes.body.permissions.filter(
      (p: any) => !(p.resource === 'webhooks' && p.action === 'write'),
    );

    // Admin removes webhooks write from viewer
    await request(app.getHttpServer())
      .post('/api/roles/viewer')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        permissions: restoredPermissions,
      })
      .expect(201);

    // Viewer tries to write to webhooks -> 403
    await request(app.getHttpServer())
      .post('/api/webhooks')
      .set('Authorization', `Bearer ${viewerToken}`)
      .send({
        targetUrl: 'http://test',
        eventTypes: [],
        secretKey: 'secret' as string,
      }) // TEST_CREDENTIAL
      .expect(403);
  });

  it('Should fetch all roles', async () => {
    const res = await request(app.getHttpServer())
      .get('/api/roles')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);

    expect(Array.isArray(res.body)).toBe(true);
    const viewerRole = res.body.find((r: any) => r.role === 'viewer');
    expect(viewerRole).toBeDefined();
    expect(Array.isArray(viewerRole.permissions)).toBe(true);
  });

  it('Should get permissions for a single role', async () => {
    const res = await request(app.getHttpServer())
      .get('/api/roles/viewer')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);

    expect(res.body.role).toBe('viewer');
    expect(Array.isArray(res.body.permissions)).toBe(true);
  });

  it('Should create and delete a new custom role', async () => {
    const roleName = 'test-custom-role';

    // Create new role by setting permissions
    await request(app.getHttpServer())
      .post(`/api/roles/${roleName}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        permissions: [{ resource: 'customers', action: 'read' }],
      })
      .expect(201);

    // Verify it exists
    const getRes = await request(app.getHttpServer())
      .get(`/api/roles/${roleName}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);

    expect(getRes.body.role).toBe(roleName);
    expect(getRes.body.permissions.length).toBe(1);

    // Delete role
    await request(app.getHttpServer())
      .delete(`/api/roles/${roleName}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);

    // Verify it's deleted (fetch permissions returns empty)
    const afterDelete = await request(app.getHttpServer())
      .get(`/api/roles/${roleName}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);

    expect(afterDelete.body.permissions.length).toBe(0);
  });

  it('Should prevent deletion of system roles', async () => {
    await request(app.getHttpServer())
      .delete('/api/roles/admin')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(400);

    await request(app.getHttpServer())
      .delete('/api/roles/viewer')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(400);
  });

  // Note: Changing a user's role and deactivating a user require actual user creation
  // and login flows in the e2e tests, which depend on the exact users endpoint setup.
});

/**
 * E2E Tests — Picking & Shipments API (Sub-Ledger Architecture)
 *
 * Exercises the new picking model where each pick is recorded in the
 * `sales_order_picks` sub-ledger with explicit bin-level tracking.
 *
 * Run with: npm run test:e2e -- --testPathPatterns picking
 * Requires: Docker stack running with Postgres + populated marts.
 */
import { TestingModule } from '@nestjs/testing';
import { createE2eModule } from './utils/e2e-module';
import { INestApplication } from '@nestjs/common';
import { register } from 'prom-client';
import { AppModule } from '../src/app.module';
import { DRIZZLE } from '../src/drizzle/drizzle.module';
import { sql } from 'drizzle-orm';

// eslint-disable-next-line @typescript-eslint/no-require-imports
const request = require('supertest');

describe('API E2E — Picking & Shipments (Sub-Ledger)', () => {
  let app: INestApplication;
  let adminToken: string;
  let viewerToken: string;
  let locationId: string;
  let validCustomerId: string;
  let validProductId: string;
  let secondProductId: string;
  let db: any;

  beforeAll(async () => {
    register.clear();

    const moduleFixture: TestingModule = await (
      await createE2eModule()
    ).compile();

    app = moduleFixture.createNestApplication();
    app.setGlobalPrefix('api');
    await app.init();

    db = app.get(DRIZZLE);

    // Clean up prior E2E data
    if (process.env.USE_PGLITE !== 'true') {
      await db.execute(sql`
      DO $$ 
      DECLARE r RECORD;
      BEGIN
        FOR r IN SELECT sales_order_id FROM modbm_core.sales_orders WHERE name LIKE 'E2E%'
        LOOP
          DELETE FROM modbm_core.sales_order_picks WHERE sales_order_id = r.sales_order_id;
          DELETE FROM modbm_core.sales_order_return_lines WHERE return_id IN (SELECT return_id FROM modbm_core.sales_order_returns WHERE sales_order_id = r.sales_order_id);
          DELETE FROM modbm_core.sales_order_returns WHERE sales_order_id = r.sales_order_id;
          DELETE FROM modbm_core.sales_order_shipment_lines WHERE shipment_id IN (SELECT shipment_id FROM modbm_core.sales_order_shipments WHERE sales_order_id = r.sales_order_id);
          DELETE FROM modbm_core.warehouse_events WHERE entity_id IN (SELECT shipment_id FROM modbm_core.sales_order_shipments WHERE sales_order_id = r.sales_order_id);
          DELETE FROM modbm_core.sales_order_shipments WHERE sales_order_id = r.sales_order_id;
          DELETE FROM modbm_core.sales_invoice_lines WHERE invoice_id IN (SELECT invoice_id FROM modbm_core.sales_invoices WHERE sales_order_id = r.sales_order_id);
          DELETE FROM modbm_core.sales_invoices WHERE sales_order_id = r.sales_order_id;
          DELETE FROM modbm_core.backorders WHERE sales_order_id = r.sales_order_id;
          DELETE FROM modbm_core.sales_order_picks WHERE sales_order_line_id IN (SELECT sales_order_line_id FROM modbm_core.sales_order_lines WHERE sales_order_id = r.sales_order_id);
          DELETE FROM modbm_core.sales_order_lines WHERE sales_order_id = r.sales_order_id;
          DELETE FROM modbm_core.sales_events WHERE entity_id = r.sales_order_id;
          DELETE FROM modbm_core.outbox WHERE entity_id = r.sales_order_id;
          DELETE FROM modbm_core.sales_orders WHERE sales_order_id = r.sales_order_id;
        END LOOP;
      END $$;
    `);
    }

    // Login as admin
    const adminLogin = await request(app.getHttpServer())
      .post('/api/auth/login')
      .send({ username: 'admin', password: process.env.ADMIN_PASSWORD })
      .expect(201);
    adminToken = adminLogin.body.access_token;

    // Login as viewer
    const viewerLogin = await request(app.getHttpServer())
      .post('/api/auth/login')
      .send({
        username: 'viewer',
        password: process.env.DEV_VIEWER_PASSWORD || 'password',
      })
      .expect(201);
    viewerToken = viewerLogin.body.access_token;

    // Fetch location
    const locRes = await request(app.getHttpServer())
      .get('/api/inventory/locations')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);
    locationId = locRes.body[0].locationId;

    // Fetch real IDs from mart data
    const customers = await request(app.getHttpServer())
      .get('/api/customers?limit=1')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);
    validCustomerId = customers.body.data[0].customerId;

    const p1 = await request(app.getHttpServer())
      .post('/api/products')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({ productNumber: 'PICK-P1', name: 'Pick Test 1', baseUom: 'EA' })
      .expect(201);
    validProductId = p1.body.productId;

    const p2 = await request(app.getHttpServer())
      .post('/api/products')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({ productNumber: 'PICK-P2', name: 'Pick Test 2', baseUom: 'EA' })
      .expect(201);
    secondProductId = p2.body.productId;
  }, 120_000);

  afterAll(async () => {
    await app.close();
  });

  // ---------------------------------------------------------------------------
  // Helpers
  // ---------------------------------------------------------------------------

  /** Create a fresh order in 'confirmed' state. */
  async function createConfirmedOrder(opts?: {
    lineQtys?: string[];
  }): Promise<{ orderId: string; lineIds: string[] }> {
    const qty1 = opts?.lineQtys?.[0] ?? '10';
    const qty2 = opts?.lineQtys?.[1] ?? '5';

    const res = await request(app.getHttpServer())
      .post('/api/sales-orders')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        fulfillmentLocationId: locationId,
        customerId: validCustomerId,
        name: 'E2E Picking Test Order',
        lines: [
          {
            productId: validProductId,
            productDescription: 'Product A',
            quantity: qty1,
            pricePerUnit: '25.00',
          },
          {
            productId: secondProductId,
            productDescription: 'Product B',
            quantity: qty2,
            pricePerUnit: '50.00',
          },
        ],
      })
      .expect((r: any) => {
        if (r.status !== 201) console.error('Order creation failed:', r.body);
      })
      .expect(201);

    const orderId = res.body.salesOrderId;

    // Advance: draft → quoted → confirmed
    for (const state of ['quoted', 'confirmed']) {
      await request(app.getHttpServer())
        .patch(`/api/sales-orders/${orderId}/state`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ stateCode: state, generateBackorders: false })
        .expect((r: any) => {
          if (r.status !== 200)
            console.error(`State change to ${state} failed:`, r.body);
        })
        .expect(200);
    }

    const detail = await request(app.getHttpServer())
      .get(`/api/sales-orders/${orderId}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);

    const lineIds = detail.body.lines.map((l: any) => l.salesOrderLineId);
    return { orderId, lineIds };
  }

  /** Resolve the storage bin ID for picking. Always use the seeded MAIN-BIN-1
   *  storage bin so we never accidentally pick FROM the SHIPPING staging bin
   *  (which would create cancelling ledger entries). */
  async function getFirstBinId(): Promise<string> {
    return '40000000-0000-0000-0000-000000000003'; // MAIN-BIN-1 from test-seed.ts
  }

  /** Pick a line via the new POST endpoint. */
  async function pickLine(
    orderId: string,
    lineId: string,
    binId: string,
    quantity: string,
    expectStatus = 201,
  ) {
    return request(app.getHttpServer())
      .post(`/api/sales-orders/${orderId}/picking/lines/${lineId}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({ binId, quantity })
      .expect((r: any) => {
        if (r.status !== expectStatus) {
          console.error(
            `pickLine expected ${expectStatus}, got ${r.status}:`,
            r.body,
          );
        }
      })
      .expect(expectStatus);
  }

  // =========================================================================
  // Full picking lifecycle via sub-ledger
  // =========================================================================

  describe('Full picking lifecycle', () => {
    let orderId: string;
    let lineIds: string[];
    let binId: string;

    beforeAll(async () => {
      const result = await createConfirmedOrder();
      orderId = result.orderId;
      lineIds = result.lineIds;
      binId = await getFirstBinId();
    });

    it('GET /picking — shows unpicked summary on confirmed order', async () => {
      const res = await request(app.getHttpServer())
        .get(`/api/sales-orders/${orderId}/picking`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      expect(res.body.totalLines).toBe(2);
      expect(res.body.fullyPickedLines).toBe(0);
      expect(res.body.isFullyPicked).toBe(false);
      expect(res.body.lines[0].remaining).toBe('10');
    });

    it('POST picking/lines/:lineId — partial pick creates sub-ledger record', async () => {
      const res = await pickLine(orderId, lineIds[0], binId, '7');

      expect(res.body).toHaveProperty('pickId');
      expect(res.body.quantity).toBe('7');

      // Verify summary updated
      const summary = await request(app.getHttpServer())
        .get(`/api/sales-orders/${orderId}/picking`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      expect(summary.body.fullyPickedLines).toBe(0);
      const line1 = summary.body.lines.find(
        (l: any) => l.salesOrderLineId === lineIds[0],
      );
      expect(line1.remaining).toBe('3');
      expect(line1.quantityPicked).toBe('7');
    });

    it('auto-transitions order from confirmed to picking on first pick', async () => {
      const detail = await request(app.getHttpServer())
        .get(`/api/sales-orders/${orderId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      expect(detail.body.stateCode).toBe('picking');
    });

    it('second pick on same line accumulates in sub-ledger', async () => {
      await pickLine(orderId, lineIds[0], binId, '3');

      const summary = await request(app.getHttpServer())
        .get(`/api/sales-orders/${orderId}/picking`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      const line1 = summary.body.lines.find(
        (l: any) => l.salesOrderLineId === lineIds[0],
      );
      expect(line1.quantityPicked).toBe('10');
      expect(line1.remaining).toBe('0');
      expect(line1.isFullyPicked).toBe(true);
      expect(summary.body.fullyPickedLines).toBe(1);
    });

    it('pick line 2 fully', async () => {
      await pickLine(orderId, lineIds[1], binId, '5');

      const summary = await request(app.getHttpServer())
        .get(`/api/sales-orders/${orderId}/picking`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      expect(summary.body.isFullyPicked).toBe(true);
      expect(summary.body.fullyPickedLines).toBe(2);
    });

    it('picks are recorded in the sales_order_picks sub-ledger', async () => {
      const res = await db.execute(sql`
        SELECT * FROM modbm_core.sales_order_picks 
        WHERE sales_order_id = ${orderId}
        ORDER BY created_on
      `);
      const picks = res.rows || res;

      // 3 picks total: 7 + 3 for line 1, 5 for line 2
      expect(picks.length).toBe(3);
      expect(picks.every((p: any) => p.state_code === 'picked')).toBe(true);
    });

    it('inventory ledger entries created for each pick', async () => {
      const res = await db.execute(sql`
        SELECT * FROM modbm_core.inventory_entries 
        WHERE source_id = ${orderId} AND source_type = 'SO_PICK'
      `);
      const entries = res.rows || res;

      expect(entries.length).toBeGreaterThan(0);
      expect(entries[0].memo).toContain('Sales Order Pick');
    });

    it('shipped BLOCKED when not all lines shipped', async () => {
      const res = await request(app.getHttpServer())
        .patch(`/api/sales-orders/${orderId}/state`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ stateCode: 'shipped' })
        .expect(400);

      expect(res.body.message).toContain('not fully shipped');
    });

    it('create shipment, dispatch, and complete lifecycle', async () => {
      const shipRes = await request(app.getHttpServer())
        .post(`/api/sales-orders/${orderId}/shipments`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          lines: [
            { salesOrderLineId: lineIds[0], quantityShipped: '10' },
            { salesOrderLineId: lineIds[1], quantityShipped: '5' },
          ],
        })
        .expect(201);

      expect(shipRes.body).toHaveProperty('shipmentId');

      // Dispatch is automatic on creation — should auto-transition order to shipped

      const detail = await request(app.getHttpServer())
        .get(`/api/sales-orders/${orderId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      expect(detail.body.stateCode).toBe('shipped');
    });
  });

  // =========================================================================
  // Validation guards
  // =========================================================================

  describe('Validation guards', () => {
    let binId: string;

    beforeAll(async () => {
      binId = await getFirstBinId();
    });

    it('rejects pick on draft order', async () => {
      const res = await request(app.getHttpServer())
        .post('/api/sales-orders')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          fulfillmentLocationId: locationId,
          customerId: validCustomerId,
          name: 'E2E Draft Guard',
          lines: [
            {
              productId: validProductId,
              quantity: '10',
              pricePerUnit: '25.00',
            },
          ],
        })
        .expect(201);

      const orderId = res.body.salesOrderId;
      const detail = await request(app.getHttpServer())
        .get(`/api/sales-orders/${orderId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      const lineId = detail.body.lines[0].salesOrderLineId;

      await request(app.getHttpServer())
        .post(`/api/sales-orders/${orderId}/picking/lines/${lineId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ binId, quantity: '5' })
        .expect(400);
    });

    it('rejects quantity exceeding ordered', async () => {
      const { orderId, lineIds } = await createConfirmedOrder({
        lineQtys: ['3', '2'],
      });

      await pickLine(orderId, lineIds[0], binId, '5', 400);
    });

    it('rejects negative quantity', async () => {
      const { orderId, lineIds } = await createConfirmedOrder();

      await request(app.getHttpServer())
        .post(`/api/sales-orders/${orderId}/picking/lines/${lineIds[0]}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ binId, quantity: '-1' })
        .expect(400);
    });

    it('rejects zero quantity', async () => {
      const { orderId, lineIds } = await createConfirmedOrder();

      await request(app.getHttpServer())
        .post(`/api/sales-orders/${orderId}/picking/lines/${lineIds[0]}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ binId, quantity: '0' })
        .expect(400);
    });

    it('rejects cumulative picks exceeding ordered quantity', async () => {
      const { orderId, lineIds } = await createConfirmedOrder({
        lineQtys: ['10', '5'],
      });

      // First pick: 7 of 10 — OK
      await pickLine(orderId, lineIds[0], binId, '7');

      // Second pick: 5 more — total would be 12 > 10 — should fail
      await pickLine(orderId, lineIds[0], binId, '5', 400);
    });

    it('rejects shipping more than picked', async () => {
      const { orderId, lineIds } = await createConfirmedOrder({
        lineQtys: ['10', '5'],
      });

      // Pick only 3
      await pickLine(orderId, lineIds[0], binId, '3');

      // Try to ship 5 — should fail
      const failRes = await request(app.getHttpServer())
        .post(`/api/sales-orders/${orderId}/shipments`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          lines: [{ salesOrderLineId: lineIds[0], quantityShipped: '5' }],
        })
        .expect(400);

      expect(failRes.body.message).toContain('only 3 available');

      // Ship 3 — should succeed
      await request(app.getHttpServer())
        .post(`/api/sales-orders/${orderId}/shipments`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          lines: [{ salesOrderLineId: lineIds[0], quantityShipped: '3' }],
        })
        .expect(201);
    });
  });

  // =========================================================================
  // Shipment document lifecycle
  // =========================================================================

  describe('Shipment document lifecycle', () => {
    let orderId: string;
    let lineIds: string[];
    let shipmentId: string;

    beforeAll(async () => {
      const result = await createConfirmedOrder();
      orderId = result.orderId;
      lineIds = result.lineIds;
      const binId = await getFirstBinId();

      // Pick all lines fully
      await pickLine(orderId, lineIds[0], binId, '10');
      await pickLine(orderId, lineIds[1], binId, '5');
    });

    it('POST /shipments — creates a shipment natively as dispatched', async () => {
      const res = await request(app.getHttpServer())
        .post(`/api/sales-orders/${orderId}/shipments`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          notes: 'First batch delivery',
          lines: [{ salesOrderLineId: lineIds[0], quantityShipped: '5' }],
        })
        .expect(201);

      expect(res.body.stateCode).toBe('dispatched');
      expect(res.body).toHaveProperty('shipmentNumber');
      shipmentId = res.body.shipmentId;
    });

    it('GET /shipments/:id — returns shipment with lines', async () => {
      const res = await request(app.getHttpServer())
        .get(`/api/sales-orders/${orderId}/shipments/${shipmentId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      expect(res.body.lines).toHaveLength(1);
      expect(res.body.lines[0].quantityShipped).toBe('5');
    });

    it('PATCH /shipments/:id — updates notes', async () => {
      const res = await request(app.getHttpServer())
        .patch(`/api/sales-orders/${orderId}/shipments/${shipmentId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ notes: 'Updated notes' })
        .expect(200);

      expect(res.body.notes).toBe('Updated notes');
    });

    it('rejects line mutations on dispatched shipment', async () => {
      // Get the existing shipment line id to test remove
      const detail = await request(app.getHttpServer())
        .get(`/api/sales-orders/${orderId}/shipments/${shipmentId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);
      const shipmentLineId = detail.body.lines[0].shipmentLineId;

      await request(app.getHttpServer())
        .post(`/api/sales-orders/${orderId}/shipments/${shipmentId}/lines`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ salesOrderLineId: lineIds[0], quantityShipped: '1' })
        .expect(400);

      await request(app.getHttpServer())
        .delete(
          `/api/sales-orders/${orderId}/shipments/${shipmentId}/lines/${shipmentLineId}`,
        )
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(400);
    });
  });

  // =========================================================================
  // Cancellation Workflow
  // =========================================================================

  describe('Cancellation Workflow', () => {
    let orderId: string;
    let lineIds: string[];
    let shipmentId: string;

    beforeAll(async () => {
      const result = await createConfirmedOrder();
      orderId = result.orderId;
      lineIds = result.lineIds;
      const binId = await getFirstBinId();

      await pickLine(orderId, lineIds[0], binId, '10');
      await pickLine(orderId, lineIds[1], binId, '5');
    });

    it('rejects transitioning to cancelled via PATCH state endpoint', async () => {
      const createRes = await request(app.getHttpServer())
        .post(`/api/sales-orders/${orderId}/shipments`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          lines: [
            { salesOrderLineId: lineIds[0], quantityShipped: '10' },
            { salesOrderLineId: lineIds[1], quantityShipped: '5' },
          ],
        })
        .expect(201);

      shipmentId = createRes.body.shipmentId;

      await request(app.getHttpServer())
        .patch(`/api/sales-orders/${orderId}/shipments/${shipmentId}/state`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ stateCode: 'cancelled' })
        .expect(400); // Bad Request
    });

    it('POST /cancel correctly cancels the shipment', async () => {
      // Order should be 'shipped' before cancellation because we shipped everything
      const detailBefore = await request(app.getHttpServer())
        .get(`/api/sales-orders/${orderId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);
      expect(detailBefore.body.stateCode).toBe('shipped');

      const res = await request(app.getHttpServer())
        .post(`/api/sales-orders/${orderId}/shipments/${shipmentId}/cancel`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect((r: any) => {
          if (r.status !== 201) console.error(r.body);
        })
        .expect(201);

      expect(res.body.stateCode).toBe('cancelled');

      // Check that the order reverted back to 'picking' because the shipment was cancelled
      const detailAfter = await request(app.getHttpServer())
        .get(`/api/sales-orders/${orderId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);
      expect(detailAfter.body.stateCode).toBe('picking');
    });
  });

  // =========================================================================
  // RBAC
  // =========================================================================

  describe('RBAC — viewer cannot pick or ship', () => {
    let orderId: string;
    let lineIds: string[];

    beforeAll(async () => {
      const result = await createConfirmedOrder();
      orderId = result.orderId;
      lineIds = result.lineIds;
    });

    it('viewer cannot pick a line (403)', async () => {
      const binId = await getFirstBinId();
      await request(app.getHttpServer())
        .post(`/api/sales-orders/${orderId}/picking/lines/${lineIds[0]}`)
        .set('Authorization', `Bearer ${viewerToken}`)
        .send({ binId, quantity: '5' })
        .expect(403);
    });

    it('viewer cannot create shipment (403)', async () => {
      await request(app.getHttpServer())
        .post(`/api/sales-orders/${orderId}/shipments`)
        .set('Authorization', `Bearer ${viewerToken}`)
        .send({
          lines: [{ salesOrderLineId: lineIds[0], quantityShipped: '5' }],
        })
        .expect(403);
    });

    it('viewer CAN read picking summary (200)', async () => {
      await request(app.getHttpServer())
        .get(`/api/sales-orders/${orderId}/picking`)
        .set('Authorization', `Bearer ${viewerToken}`)
        .expect(200);
    });

    it('viewer CAN read shipments (200)', async () => {
      await request(app.getHttpServer())
        .get(`/api/sales-orders/${orderId}/shipments`)
        .set('Authorization', `Bearer ${viewerToken}`)
        .expect(200);
    });
  });
});

