import { TestingModule } from '@nestjs/testing';
import { createE2eModule } from './utils/e2e-module';
import { INestApplication } from '@nestjs/common';
import { AppModule } from '../src/app.module';

// eslint-disable-next-line @typescript-eslint/no-require-imports
const request = require('supertest');

describe('Product Groups (e2e)', () => {
  let app: INestApplication;
  let adminToken: string;

  beforeAll(async () => {
    const moduleFixture: TestingModule = await (
      await createE2eModule()
    ).compile();

    app = moduleFixture.createNestApplication();
    app.setGlobalPrefix('api');
    await app.init();

    // Login as admin
    const adminRes = await request(app.getHttpServer())
      .post('/api/auth/login')
      .send({
        username: 'admin',
        password: process.env.ADMIN_PASSWORD || 'password',
      });
    if (adminRes.status !== 201) {
      throw new Error(
        `${'adminRes'} login failed: ${adminRes.status} ${JSON.stringify(adminRes.body)}`,
      );
    }
    adminToken = adminRes.body.access_token;
  });

  afterAll(async () => {
    await app.close();
  });

  it('CRUD /api/product-groups — full lifecycle', async () => {
    const groupCode = `PROD-GRP-${Date.now()}`;

    // 1. Create a group
    const createRes = await request(app.getHttpServer())
      .post('/api/product-groups')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        groupCode,
        name: 'E2E Test Product Group',
      });
    expect(createRes.status).toBe(201);
    expect(createRes.body.productGroupId).toBeDefined();
    expect(createRes.body.groupCode).toBe(groupCode);
    const groupId = createRes.body.productGroupId;

    // 2. Read all groups
    const listRes = await request(app.getHttpServer())
      .get('/api/product-groups')
      .set('Authorization', `Bearer ${adminToken}`);
    expect(listRes.status).toBe(200);
    expect(Array.isArray(listRes.body)).toBe(true);
    expect(
      listRes.body.find((g: any) => g.productGroupId === groupId),
    ).toBeDefined();

    // 3. Read single group
    const getRes = await request(app.getHttpServer())
      .get(`/api/product-groups/${groupId}`)
      .set('Authorization', `Bearer ${adminToken}`);
    expect(getRes.status).toBe(200);
    expect(getRes.body.name).toBe('E2E Test Product Group');

    // 4. Assign a product to the group
    const createProductRes = await request(app.getHttpServer())
      .post('/api/products')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        productNumber: `GRP-MEMBER-${Date.now()}`,
        name: 'Group Member Product',
        productGroupId: groupId,
        listPrice: '10.00',
      });
    expect(createProductRes.status).toBe(201);
    expect(createProductRes.body.productGroupId).toBe(groupId);

    // 5. Verify the group name merges into the product payload correctly
    const productRes = await request(app.getHttpServer())
      .get(`/api/products/${createProductRes.body.productId}`)
      .set('Authorization', `Bearer ${adminToken}`);
    const foundAcc = productRes.body;
    expect(foundAcc.productId).toBeDefined();
    expect(foundAcc.productGroupCode).toBe(groupCode);
    expect(foundAcc.productGroupName).toBe('E2E Test Product Group');

    // 6. Update the group
    const updateRes = await request(app.getHttpServer())
      .patch(`/api/product-groups/${groupId}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        name: 'Updated Product Group',
      });
    expect(updateRes.status).toBe(200);
    expect(updateRes.body.name).toBe('Updated Product Group');

    // 7. Delete the group (first cleanly un-assign the product to avoid FK errors)
    await request(app.getHttpServer())
      .patch(`/api/products/${createProductRes.body.productId}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({ productGroupId: null });

    const deleteRes = await request(app.getHttpServer())
      .delete(`/api/product-groups/${groupId}`)
      .set('Authorization', `Bearer ${adminToken}`);
    expect(deleteRes.status).toBe(200);
    expect(deleteRes.body.deleted).toBe(true);
  });
});

/**
 * E2E Tests — Purchase Invoices & GL Integration
 */
import { TestingModule } from '@nestjs/testing';
import { createE2eModule } from './utils/e2e-module';
import { INestApplication } from '@nestjs/common';
import { register } from 'prom-client';
import { AppModule } from '../src/app.module';

// eslint-disable-next-line @typescript-eslint/no-require-imports
const request = require('supertest');

describe('API E2E — Purchase Invoices', () => {
  let app: INestApplication;
  let adminToken: string;
  let validVendorId: string;
  let validProductId: string;
  let validLocationId: string;

  beforeAll(async () => {
    register.clear();

    const moduleFixture: TestingModule = await (
      await createE2eModule()
    ).compile();

    app = moduleFixture.createNestApplication();
    app.setGlobalPrefix('api');
    await app.init();

    // Login as admin
    const adminLogin = await request(app.getHttpServer())
      .post('/api/auth/login')
      .send({ username: 'admin', password: process.env.ADMIN_PASSWORD })
      .expect(201);
    adminToken = adminLogin.body.access_token;

    // Fetch GL accounts to use for AP and Expense
    const accountsRes = await request(app.getHttpServer())
      .get('/api/gl/accounts')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);

    const leaves: any[] = [];
    const walk = (nodes: any[]) => {
      for (const node of nodes) {
        if (!node.isGroup) leaves.push(node);
        if (node.children) walk(node.children);
      }
    };
    walk(accountsRes.body);

    // Pick two accounts
    const apAccount = leaves.find((l) => l.accountCode === '2100') || leaves[0];
    const expAccount =
      leaves.find((l) => l.accountCode === '5100') || leaves[1];

    // Create an app vendor (core UUID) to guarantee valid UUID vendorId
    const vendorRes = await request(app.getHttpServer())
      .post('/api/suppliers')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        address1Country: 'AU',
        vendorNumber: `E2E-VEND-${Date.now()}`,
        name: 'E2E Test Vendor for Invoices',
        defaultApAccountId: apAccount.glAccountId,
        defaultExpenseAccountId: expAccount.glAccountId,
      })
      .expect(201);
    validVendorId = vendorRes.body.vendorId;

    // Create an app product (core UUID) for use in PO lines
    const productRes = await request(app.getHttpServer())
      .post('/api/products')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        productNumber: `E2E-INV-P-${Date.now()}`,
        name: 'E2E Invoice Test Product',
        listPrice: '15.00',
      })
      .expect(201);
    validProductId = productRes.body.productId;

    await request(app.getHttpServer())
      .post(`/api/products/${validProductId}/suppliers`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        vendorId: validVendorId,
        isPreferred: true,
        costPrice: '10.00',
        minOrderQty: 1,
      })
      .expect(201);

    // Fetch a base delivery location
    const locationsRes = await request(app.getHttpServer())
      .get('/api/inventory/locations')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);
    validLocationId = locationsRes.body[0].locationId;
  }, 120_000);

  afterAll(async () => {
    await app.close();
  });

  describe('Purchase Invoice Lifecycle', () => {
    let orderId: string;
    let createdInvoiceId: string;

    it('creates and invoices a fully received purchase order', async () => {
      // 1. Create order
      const today = new Date().toISOString().slice(0, 10).replace(/-/g, '');
      const rand = Math.random().toString(36).substring(2, 6).toUpperCase();

      const createRes = await request(app.getHttpServer())
        .post('/api/purchase-orders')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          orderNumber: `E2E-INV-PO-${today}-${rand}`,
          vendorId: validVendorId,
          deliveryLocationId: validLocationId,
          name: 'E2E Invoice Test',
          currencyCode: 'AUD',
          lines: [
            {
              productId: validProductId,
              quantity: '5',
              pricePerUnit: '12.00',
            },
          ],
        });
      if (createRes.status !== 201) {
        console.error('PO CREATION ERROR:', createRes.body);
      }
      expect(createRes.status).toBe(201);

      orderId = createRes.body.purchaseOrderId;

      // 2. Transition state and receive
      await request(app.getHttpServer())
        .patch(`/api/purchase-orders/${orderId}/state`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ stateCode: 'ordered' })
        .expect(200);

      // Get line IDs
      const detail = await request(app.getHttpServer())
        .get(`/api/purchase-orders/${orderId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);
      const lineId = detail.body.lines[0].purchaseOrderLineId;

      await request(app.getHttpServer())
        .post(`/api/goods-received`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          vendorId: validVendorId,
          locationId: validLocationId,
          packingSlipNumber: `TEST-PS-${rand}`,
          lines: [{ productId: validProductId, quantityReceived: '5' }],
        })
        .expect(201);

      // The reception of full quantity automatically transitions the order to 'received'

      // 3. Generate Invoice
      const invoiceRes = await request(app.getHttpServer())
        .post(`/api/purchase-invoices`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          vendorId: validVendorId,
          supplierInvoiceNumber: `SUPP-INV-${rand}`,
          currencyCode: 'AUD',
          purchaseOrderId: orderId,
          totalAmount: 60.0,
          taxAmount: 0,
          notes: 'Test AP invoicing',
          lines: [
            {
              description: 'E2E Invoice Test Product',
              productId: validProductId,
              quantityInvoiced: 5,
              pricePerUnit: 12.0,
              purchaseOrderLineId: lineId,
            },
          ],
        })
        .expect(201);

      createdInvoiceId = invoiceRes.body.invoiceId;
      expect(createdInvoiceId).toBeDefined();

      // 4. Post the invoice to generate GL entries
      await request(app.getHttpServer())
        .post(`/api/purchase-invoices/${createdInvoiceId}/post`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);
    });

    it('GL Integration — posted a journal entry for the AP invoice', async () => {
      const glRes = await request(app.getHttpServer())
        .get(`/api/gl/journal-entries?sourceType=purchase_invoice`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      const je = glRes.body.data.find(
        (j: any) => j.sourceId === createdInvoiceId,
      );
      expect(je).toBeDefined();

      const detailRes = await request(app.getHttpServer())
        .get(`/api/gl/journal-entries/${je.journalEntryId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      const lines = detailRes.body.lines;
      expect(lines.length).toBeGreaterThanOrEqual(2);

      // AP Line should be the credit line for the supplier
      const apLine = lines.find(
        (l: any) => l.partyId === validVendorId && parseFloat(l.credit) > 0,
      );
      expect(apLine).toBeDefined();
      expect(apLine.partyType).toBe('supplier');
      expect(parseFloat(apLine.credit)).toBeGreaterThan(59.0);

      // Verify outbox event
      const dbRes = await request(app.getHttpServer())
        .get(
          '/api/settings/external-sync/events?type=general_ledger.entry_posted',
        )
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      const eventsList = dbRes.body.events || [];
      const glEvent = eventsList.find(
        (evt: any) =>
          evt.eventType === 'general_ledger.entry_posted' &&
          evt.entityId === je.journalEntryId,
      );
      expect(glEvent).toBeDefined();
    });

    it('Cancels the AP invoice and verifies the GL reversal is posted', async () => {
      // 1. Cancel the invoice
      await request(app.getHttpServer())
        .patch(`/api/purchase-invoices/${createdInvoiceId}/state`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ stateCode: 'cancelled' })
        .expect(200);

      // 2. Fetch the GL reversals
      const glRes = await request(app.getHttpServer())
        .get(`/api/gl/journal-entries?sourceType=purchase_invoice_reversal`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      const je = glRes.body.data.find(
        (j: any) => j.sourceId === createdInvoiceId,
      );
      expect(je).toBeDefined();

      const detailRes = await request(app.getHttpServer())
        .get(`/api/gl/journal-entries/${je.journalEntryId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      const lines = detailRes.body.lines;
      expect(lines.length).toBeGreaterThanOrEqual(2);

      // Reversal AP Line should be the DEBIT line for the supplier
      const apReversalLine = lines.find(
        (l: any) => l.partyId === validVendorId && parseFloat(l.debit) > 0,
      );
      expect(apReversalLine).toBeDefined();
      expect(apReversalLine.partyType).toBe('supplier');
      expect(parseFloat(apReversalLine.debit)).toBeGreaterThan(59.0);
    });
  });
});

/**
 * E2E Tests — Purchase Order Returns API
 *
 * These tests exercise the purchase return endpoints on PurchaseReturnsController
 * against a real Postgres database (modbm_core schema). They verify
 * the return draft creation, fetching, actioning (which does inventory deduction),
 * and RBAC enforcement.
 *
 * Run with: npm run test:e2e -- --testPathPatterns purchase-returns
 * Requires: Docker stack running with Postgres + populated marts.
 */
import { TestingModule } from '@nestjs/testing';
import { createE2eModule } from './utils/e2e-module';
import { INestApplication } from '@nestjs/common';
import { register } from 'prom-client';
import { AppModule } from '../src/app.module';
import { PURCHASE_ORDER_STATE, PURCHASE_RETURN_STATE } from '@modbm/shared';

// eslint-disable-next-line @typescript-eslint/no-require-imports
const request = require('supertest');

describe('API E2E — Purchase Order Returns', () => {
  let app: INestApplication;
  let adminToken: string;
  let viewerToken: string;

  let validVendorId: string;
  let appProductId: string;
  let validLocationId: string;

  beforeAll(async () => {
    register.clear();

    const moduleFixture: TestingModule = await (
      await createE2eModule()
    ).compile();

    app = moduleFixture.createNestApplication();
    app.setGlobalPrefix('api');
    await app.init();

    // Login
    const adminLogin = await request(app.getHttpServer())
      .post('/api/auth/login')
      .send({
        username: 'admin',
        password: process.env.ADMIN_PASSWORD || 'password',
      })
      .expect(201);
    adminToken = adminLogin.body.access_token;

    const viewerLogin = await request(app.getHttpServer())
      .post('/api/auth/login')
      .send({
        username: 'viewer',
        password: process.env.DEV_VIEWER_PASSWORD || 'password',
      })
      .expect(201);
    viewerToken = viewerLogin.body.access_token;

    // Create an app product for use in PO lines
    const productRes = await request(app.getHttpServer())
      .post('/api/products')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        productNumber: `E2E-PRET-P-${Date.now()}`,
        name: 'E2E Purchase Return Test Product',
        listPrice: '15.00',
      })
      .expect(201);
    appProductId = productRes.body.productId;

    // Fetch real supplier
    const suppliers = await request(app.getHttpServer())
      .get('/api/suppliers?limit=1')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);
    validVendorId = suppliers.body.data[0].vendorId;

    await request(app.getHttpServer())
      .post(`/api/products/${appProductId}/suppliers`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        vendorId: validVendorId,
        isPreferred: true,
        costPrice: '15.00',
        minOrderQty: 1,
      })
      .expect(201);

    // Fetch a base delivery location
    const locationsRes = await request(app.getHttpServer())
      .get('/api/inventory/locations')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);
    validLocationId = locationsRes.body[0].locationId;
  }, 120_000);

  afterAll(async () => {
    await app.close();
  });

  /**
   * Helper: Create a purchase order, advance to ordered, receive it to make it returnable.
   */
  async function createReceivedPO(): Promise<{
    purchaseOrderId: string;
    lineIds: string[];
  }> {
    const today = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    const rand = Math.random().toString(36).substring(2, 6).toUpperCase();

    const createRes = await request(app.getHttpServer())
      .post('/api/purchase-orders')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        orderNumber: `E2E-PRET-PO-${today}-${rand}`,
        name: 'E2E Purchase Return Test PO',
        vendorId: validVendorId,
        deliveryLocationId: validLocationId,
        currencyCode: 'EUR',
        lines: [
          {
            productId: appProductId,
            productDescription: 'Return Test Product',
            quantity: '20',
            pricePerUnit: '15.00',
            unitOfMeasure: 'EA',
          },
        ],
      })
      .expect(201);

    const purchaseOrderId = createRes.body.purchaseOrderId;

    // Advance to ordered
    await request(app.getHttpServer())
      .patch(`/api/purchase-orders/${purchaseOrderId}/state`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({ stateCode: PURCHASE_ORDER_STATE.ORDERED })
      .expect(200);

    // Get line IDs
    const detail = await request(app.getHttpServer())
      .get(`/api/purchase-orders/${purchaseOrderId}`)
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);

    const lineIds = detail.body.lines.map((l: any) => l.purchaseOrderLineId);

    // Receive the items to ensure they are returnable
    await request(app.getHttpServer())
      .post('/api/goods-received')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        vendorId: validVendorId,
        locationId: validLocationId,
        packingSlipNumber: 'PS-PRET',
        notes: 'Initial receipt for return test',
        lines: [
          {
            productId: appProductId,
            quantityReceived: '10',
          },
        ],
      })
      .expect(201);

    return { purchaseOrderId, lineIds };
  }

  // =========================================================================
  // Purchase Return lifecycle
  // =========================================================================

  describe('Purchase Return lifecycle', () => {
    let purchaseOrderId: string;
    let lineIds: string[];
    let returnId: string;

    beforeAll(async () => {
      const result = await createReceivedPO();
      purchaseOrderId = result.purchaseOrderId;
      lineIds = result.lineIds;
    });

    it('POST /returns — creates a draft return', async () => {
      const res = await request(app.getHttpServer())
        .post(`/api/purchase-orders/${purchaseOrderId}/returns`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          notes: 'Defective units returned',
          lines: [
            {
              purchaseOrderLineId: lineIds[0],
              quantityReturned: '3',
              returnFee: '15.00',
            },
          ],
        })
        .expect(201);

      expect(res.body).toHaveProperty('returnId');
      expect(res.body).toHaveProperty('stateCode', PURCHASE_RETURN_STATE.DRAFT);
      returnId = res.body.returnId;
    });

    it('GET /returns — lists returns for the PO', async () => {
      const res = await request(app.getHttpServer())
        .get(`/api/purchase-orders/${purchaseOrderId}/returns`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      expect(Array.isArray(res.body)).toBe(true);
      expect(res.body.length).toBeGreaterThanOrEqual(1);
    });

    it('GET /returns/:id — retrieves return detail', async () => {
      const res = await request(app.getHttpServer())
        .get(`/api/purchase-orders/${purchaseOrderId}/returns/${returnId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      expect(res.body.returnId).toBe(returnId);
      expect(res.body.notes).toBe('Defective units returned');
      expect(res.body.lines[0]).toHaveProperty('quantityReturned', '3');
    });

    it('POST /returns/:id/action — actions the return (deducts inventory)', async () => {
      // Stage the return first
      await request(app.getHttpServer())
        .post(
          `/api/purchase-orders/${purchaseOrderId}/returns/${returnId}/stage`,
        )
        .set('Authorization', `Bearer ${adminToken}`)
        .send({})
        .expect(200);

      // Ship the return
      const res = await request(app.getHttpServer())
        .post(
          `/api/purchase-orders/${purchaseOrderId}/returns/${returnId}/ship`,
        )
        .set('Authorization', `Bearer ${adminToken}`)
        .send({})
        .expect(200);

      expect(res.body.returnId).toBe(returnId);
      expect(res.body.stateCode).toBe(PURCHASE_RETURN_STATE.SHIPPED); // Returns flow immediately marks it as processed
    });
  });

  // =========================================================================
  // RBAC — viewer cannot create returns
  // =========================================================================

  describe('RBAC — viewer cannot create purchase returns', () => {
    let purchaseOrderId: string;
    let lineIds: string[];

    beforeAll(async () => {
      const result = await createReceivedPO();
      purchaseOrderId = result.purchaseOrderId;
      lineIds = result.lineIds;
    });

    it('viewer cannot create a purchase return (403)', async () => {
      await request(app.getHttpServer())
        .post(`/api/purchase-orders/${purchaseOrderId}/returns`)
        .set('Authorization', `Bearer ${viewerToken}`)
        .send({
          notes: 'viewer attempt',
          lines: [{ purchaseOrderLineId: lineIds[0], quantityReturned: '1' }],
        })
        .expect(403);
    });

    it('viewer CAN read purchase returns (200)', async () => {
      await request(app.getHttpServer())
        .get(`/api/purchase-orders/${purchaseOrderId}/returns`)
        .set('Authorization', `Bearer ${viewerToken}`)
        .expect(200);
    });
  });
});

import { TestingModule } from '@nestjs/testing';
import { createE2eModule } from './utils/e2e-module';
import { INestApplication } from '@nestjs/common';
import { AppModule } from '../src/app.module';

// eslint-disable-next-line @typescript-eslint/no-require-imports
const request = require('supertest');

describe('Dynamic Reports Engine (e2e)', () => {
  let app: INestApplication;
  let adminToken: string;
  let locationId: string;

  beforeAll(async () => {
    const moduleFixture: TestingModule = await (
      await createE2eModule()
    ).compile();

    app = moduleFixture.createNestApplication();
    app.setGlobalPrefix('api');
    await app.init();

    // Login as admin
    const adminRes = await request(app.getHttpServer())
      .post('/api/auth/login')
      .send({
        username: 'admin',
        password: process.env.ADMIN_PASSWORD || 'password',
      });

    if (adminRes.status !== 201) {
      throw new Error(
        `${'adminRes'} login failed: ${adminRes.status} ${JSON.stringify(adminRes.body)}`,
      );
    }
    adminToken = adminRes.body.access_token;
    const locRes = await request(app.getHttpServer())
      .get('/api/inventory/locations')
      .set('Authorization', `Bearer ${adminToken}`)
      .expect(200);
    locationId = locRes.body[0].locationId;
  });

  afterAll(async () => {
    await app.close();
  });

  it('POST /api/pdf-templates/hooks/:hookSlug/run — handles sparse data (App Orders) without crashing Typst', async () => {
    // 1. Fetch valid foreign keys required for minimal creation
    const customers = await request(app.getHttpServer())
      .get('/api/customers?limit=1')
      .set('Authorization', `Bearer ${adminToken}`);

    const products = await request(app.getHttpServer())
      .get('/api/products?limit=1')
      .set('Authorization', `Bearer ${adminToken}`);

    if (!customers.body.data?.length || !products.body.data?.length) {
      console.warn('Missing test data for sparse order generation.');
      return;
    }

    // 2. Insert the sparsest possible order (no product number, no customer name, etc)
    const draftRes = await request(app.getHttpServer())
      .post('/api/sales-orders')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        fulfillmentLocationId: locationId,

        customerId: customers.body.data[0].customerId,
        lines: [
          {
            productId: products.body.data[0].productId,
            quantity: '1',
            pricePerUnit: '10.00',
          },
        ],
      });

    expect(draftRes.status).toBe(201);
    const orderId = draftRes.body.salesOrderId;

    // 3. Execute the Quote Hook against the sparse order
    const pdfRes = await request(app.getHttpServer())
      .post(
        `/api/pdf-templates/hooks/sales-order-quote/run?id=${orderId}&context=sales-order`,
      )
      .set('Authorization', `Bearer ${adminToken}`)
      .responseType('blob');

    // NestJS @Post routes default to 201, but we added @HttpCode(200)
    expect(pdfRes.status).toBe(200);
    expect(pdfRes.headers['content-type']).toBe('application/pdf');

    const buf = pdfRes.body;
    expect(buf.subarray(0, 5).toString('utf8')).toBe('%PDF-');
  }, 10000);

