import { Test, TestingModuleBuilder } from '@nestjs/testing';
import { AppModule } from '../../src/app.module';
import { DRIZZLE, POSTGRES_CLIENT } from '../../src/drizzle/drizzle.module';
// PGlite imports removed from static scope to prevent Node from evaluating
// ES modules when PGlite is not in use (avoids ERR_VM_DYNAMIC_IMPORT_CALLBACK_MISSING_FLAG)
import * as schema from '../../src/drizzle/modbm-core-schema';
import * as fs from 'fs';
import * as path from 'path';

export async function createE2eModule(): Promise<TestingModuleBuilder> {
  let builder = Test.createTestingModule({
    imports: [AppModule],
  });

  if (process.env.USE_PGLITE === 'true') {
    const snapshotPath = path.join(process.cwd(), '.pglite-snapshot.bin');
    if (!fs.existsSync(snapshotPath)) {
      throw new Error(
        'PGlite snapshot not found. Did you forget to run generate-snapshot.ts?',
      );
    }
    const buffer = fs.readFileSync(snapshotPath);
    const suiteSnapshot = new File([buffer], 'snapshot.tar');

    // Dynamically import PGlite only when needed
    const { PGlite } = await import('@electric-sql/pglite');
    const { drizzle: drizzlePglite } = await import('drizzle-orm/pglite');

    const client = new PGlite({ loadDataDir: suiteSnapshot });
    await client.waitReady;
    const db = drizzlePglite({ client, schema, casing: 'snake_case' } as any);

    builder = builder
      .overrideProvider(DRIZZLE)
      .useValue(db)
      .overrideProvider(POSTGRES_CLIENT)
      .useValue({ end: async () => await client.close() });
  }

  return builder;
}

import { getTableName } from 'drizzle-orm';

function extractTableName(table: any): string {
  if (typeof table === 'string') return table;
  try {
    return getTableName(table);
  } catch (e) {
    // Fallback if not a drizzle table
    if (table && table._ && table._.name) return table._.name;
    if (table && table.name) return table.name;
    return 'unknown';
  }
}

function createMockQueryBuilder(resolveDataFn: () => any) {
  const qb: any = {
    where: jest.fn().mockReturnThis(),
    innerJoin: jest.fn().mockReturnThis(),
    leftJoin: jest.fn().mockReturnThis(),
    orderBy: jest.fn().mockReturnThis(),
    limit: jest.fn().mockReturnThis(),
    groupBy: jest.fn().mockReturnThis(),
    having: jest.fn().mockReturnThis(),
    values: jest.fn().mockReturnThis(),
    set: jest.fn().mockReturnThis(),
    returning: jest
      .fn()
      .mockImplementation(() => Promise.resolve(resolveDataFn())),
    then: jest.fn().mockImplementation((cb) => {
      const data = resolveDataFn();
      if (typeof cb === 'function') {
        return Promise.resolve(data).then(cb);
      }
      return Promise.resolve(data);
    }),
  };
  return qb;
}

export class MockDrizzle {
  private tableMocks = new Map<string, any[] | (() => any[])>();
  private defaultMock: any[] = [];
  public _selectQb: any;

  constructor() {
    this._selectQb = createMockQueryBuilder(() => this.defaultMock);
  }

  /**
   * Mocks the return value of a query when it targets a specific table.
   * Use the Drizzle schema object (e.g., `schema.products`) or string name.
   */
  onTable(table: any, data: any[] | (() => any[])) {
    const tableName = extractTableName(table);
    this.tableMocks.set(tableName, data);
    return this;
  }

  private resolveMock(currentTable: string | null) {
    if (currentTable && this.tableMocks.has(currentTable)) {
      const mock = this.tableMocks.get(currentTable);
      return typeof mock === 'function' ? mock() : mock;
    }
    return typeof this.defaultMock === 'function'
      ? (this.defaultMock as any)()
      : this.defaultMock;
  }

  setDefault(data: any[]) {
    this.defaultMock = data;
    return this;
  }

  clearMocks() {
    this.tableMocks.clear();
    this.defaultMock = [];
  }

  select = jest.fn().mockImplementation(() => {
    let currentTable: string | null = null;

    const qb = createMockQueryBuilder(() => this.resolveMock(currentTable));

    qb.from = jest.fn().mockImplementation((table: any) => {
      currentTable = extractTableName(table);
      return qb;
    });

    return qb;
  });

  insert = jest.fn().mockImplementation((table: any) => {
    const currentTable = extractTableName(table);
    return createMockQueryBuilder(() => {
      const resolved = this.resolveMock(currentTable);
      return resolved.length ? resolved : [{}];
    });
  });

  update = jest.fn().mockImplementation((table: any) => {
    const currentTable = extractTableName(table);
    return createMockQueryBuilder(() => {
      const resolved = this.resolveMock(currentTable);
      return resolved.length ? resolved : [{}];
    });
  });

  delete = jest.fn().mockImplementation((table: any) => {
    const currentTable = extractTableName(table);
    return createMockQueryBuilder(() => {
      const resolved = this.resolveMock(currentTable);
      return resolved.length ? resolved : [{}];
    });
  });

  transaction = jest.fn().mockImplementation(async (cb: any) => {
    // In a transaction, we just pass this same instance, or a clone that shares mocks
    return cb(this);
  });
}

/**
 * E2E Database Provisioner
 *
 * Creates a dedicated ephemeral database for E2E testing so that the
 * main dev instance is never polluted. Run before the E2E Jest suite.
 *
 * Flow:
 *   1. Connect to Postgres as superuser (uses the default POSTGRES_* env vars).
 *   2. DROP / CREATE a fresh database named `modbm_e2e_test`.
 *   3. Run all SQL migrations from apps/api/migrations/ against it.
 *   4. Run the standard application seeds (users, COA, locations, etc.).
 *   5. Print the connection details so the caller can export them.
 */
import * as dotenv from 'dotenv';
import * as path from 'path';
import * as fs from 'fs';

// Load environment from monorepo root .env
const rootEnv = path.resolve(__dirname, '..', '..', '..', '..', '.env');
dotenv.config({ path: rootEnv });

import postgres from 'postgres';
import { drizzle } from 'drizzle-orm/postgres-js';
import * as schema from '../../src/drizzle/modbm-core-schema';
import {
  runStandardSeeds,
  seedCoaSettings,
  seedCoaAccounts,
  seedAccounts,
} from '../../src/scripts/seed';
import { seedTestLocations } from './test-seed';

const E2E_DB_NAME = 'modbm_e2e_test';

async function provision() {
  const host = process.env.POSTGRES_HOST || 'localhost';
  const port = Number(process.env.POSTGRES_PORT || 5432);
  const user = process.env.POSTGRES_USER || 'postgres';
  const password = process.env.POSTGRES_PASSWORD;

  if (!password) {
    console.error(
      'POSTGRES_PASSWORD is not set. Cannot provision E2E database.',
    );
    process.exit(1);
  }

  // 1. Connect to the default 'postgres' database to issue CREATE/DROP
  const adminSql = postgres({
    host,
    port,
    user,
    password,
    database: 'postgres',
    max: 1,
  });

  console.log(`[E2E DB] Provisioning database "${E2E_DB_NAME}"...`);

  try {
    // Terminate existing connections to the test DB
    await adminSql`
      SELECT pg_terminate_backend(pid)
      FROM pg_stat_activity
      WHERE datname = ${E2E_DB_NAME} AND pid <> pg_backend_pid()
    `;
    await adminSql.unsafe(`DROP DATABASE IF EXISTS "${E2E_DB_NAME}"`);
    await adminSql.unsafe(`CREATE DATABASE "${E2E_DB_NAME}"`);
    console.log(`[E2E DB] Database "${E2E_DB_NAME}" created.`);
  } finally {
    await adminSql.end();
  }

  // 2. Connect to the new E2E database and run migrations
  const e2eSql = postgres({
    host,
    port,
    user,
    password,
    database: E2E_DB_NAME,
  });

  try {
    // Create schema
    await e2eSql`CREATE SCHEMA IF NOT EXISTS modbm_core`;

    // Run migration files in order
    const migrationsDir = path.join(__dirname, '..', '..', 'migrations');
    const files = fs
      .readdirSync(migrationsDir)
      .filter((f) => f.endsWith('.sql'))
      .sort();

    for (const file of files) {
      let sql = fs.readFileSync(path.join(migrationsDir, file), 'utf8');
      sql = sql.replace(/^\uFEFF/, ''); // strip BOM
      try {
        await e2eSql.unsafe(sql);
      } catch (e: any) {
        console.warn(`  Migration warning on ${file}: ${e.message}`);
      }
    }
    console.log(`[E2E DB] ${files.length} migrations applied.`);

    // Schema drift catch-up (in Drizzle schema but not yet in a migration file)
    await e2eSql.unsafe(`
      ALTER TABLE "modbm_core"."sales_invoices"
        ADD COLUMN IF NOT EXISTS "outstanding_amount" numeric DEFAULT '0' NOT NULL;
      ALTER TABLE "modbm_core"."purchase_invoices"
        ADD COLUMN IF NOT EXISTS "outstanding_amount" numeric DEFAULT '0' NOT NULL;
    `);

    // Apply extensions if present
    const extensionsFile = path.join(
      __dirname,
      '..',
      '..',
      'src',
      'drizzle',
      'extensions.sql',
    );
    if (fs.existsSync(extensionsFile)) {
      let extSql = fs.readFileSync(extensionsFile, 'utf8');
      extSql = extSql.replace(/^\uFEFF/, '');
      try {
        await e2eSql.unsafe(extSql);
        console.log('[E2E DB] Extensions applied.');
      } catch (e: any) {
        console.warn(`  Extensions warning: ${e.message}`);
      }
    }

    // 3. Seed the database
    const db = drizzle(e2eSql, { schema });
    await runStandardSeeds(db);
    // Testing-only extension to seed COA defaults, accounts, and locations for E2E
    await seedCoaAccounts(db, false);
    await seedCoaSettings(db, false);
    await seedTestLocations(db, false);
    await seedAccounts(db, false);
    console.log('[E2E DB] Seeds applied.');
  } finally {
    await e2eSql.end();
  }

  console.log(
    `[E2E DB] Ready. Set POSTGRES_DB=${E2E_DB_NAME} for the test run.`,
  );
}

provision().catch((err) => {
  console.error('[E2E DB] Provisioning failed:', err);
  process.exit(1);
});

